    /// Aggregate journal schema 2 format: V1/V2 keep their frozen flat records
    /// digest; every V3...V53 candidate uses the bounded framed layer digest.
    /// Nested canonical bytes grow by base64 (4/3) per release and are never
    /// materialized on the skipped-release upgrade path.
    @MainActor
    private func aggregateSemanticDigest(
        in context: ModelContext,
        release: PersistentSchemaReleaseV1
    ) throws -> String {
        guard release.versionIdentifier.major >= 3 else {
            return StoreMigrationCanonicalJSONV1.sha256(try semanticProjection(in: context, release: release))
        }
        return try framedSemanticDigest(in: context, release: release)
    }

    /// The original single-step journal keeps its recorded nested digests; only
    /// the aggregate journal (schema 2) uses the framed format.
    @MainActor
    private func adjacentSemanticDigest(
        in context: ModelContext,
        release: PersistentSchemaReleaseV1,
        aggregate: StoreAggregateMigrationJournalV1?
    ) throws -> String {
        guard aggregate != nil else {
            return StoreMigrationCanonicalJSONV1.sha256(try semanticProjection(in: context, release: release))
        }
        return try aggregateSemanticDigest(in: context, release: release)
    }

    @MainActor
    private func framedSemanticDigest(
        in context: ModelContext,
        release: PersistentSchemaReleaseV1
    ) throws -> String {
        var digest = try StoreSemanticLayerDigestV1(release: release)
        var purpose = StoreSemanticExportPurposeV1.validationOnly
        purpose.consumeLayer = { try digest.append($0) }
        _ = try semanticProjection(in: context, release: release, purpose: purpose)
        return try digest.finalize()
    }

    @MainActor
    private func framedSemanticDigest(
        at modelStoreURL: URL,
        release: PersistentSchemaReleaseV1,
        markerMigrationID: UUID? = nil
    ) throws -> String {
        try autoreleasepool {
            let container = try openReleasedContainer(
                at: modelStoreURL, release: release, markerMigrationID: markerMigrationID
            )
            return try framedSemanticDigest(in: container.mainContext, release: release)
        }
    }

    /// Verify the recorded format only. A mismatch never falls back to another hash.
    @MainActor
    private func semanticDigest(
        at modelStoreURL: URL,
        manifest: StoreGenerationManifestV1
    ) throws -> String {
        try manifest.validate()
        return try autoreleasepool {
            let container = try openReleasedContainer(
                at: modelStoreURL, release: manifest.storeSchemaRelease, markerMigrationID: nil
            )
            return try semanticDigest(in: container.mainContext, manifest: manifest)
        }
    }

    @MainActor
    private func semanticDigest(
        in context: ModelContext,
        manifest: StoreGenerationManifestV1
    ) throws -> String {
        try manifest.validate()
