    private func reconcileRestorePointerTemporary(name: String) throws {
        let temporary = ".\(name).restore-next"
        guard try Self.itemExists(
            parent: dataDescriptor,
            name: temporary
        ) else {
            return
        }

        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        guard try Self.itemExists(
            parent: dataDescriptor,
            name: temporary
        ) else {
            return
        }
        try verify()
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent(name, isDirectory: false)
        )
        try enforce(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(temporary, isDirectory: false)
        )
        let current = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: name
        )
        let candidate = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: temporary
        )
        switch name {
        case "current.json":
            _ = try CurrentPointerCodecV1.decode(current.data)
            _ = try CurrentPointerCodecV1.decode(candidate.data)
        case "retired.json":
            let currentValue = try JSONDecoder().decode(
                RetiredPointerV1.self,
                from: current.data
            )
            let candidateValue = try JSONDecoder().decode(
                RetiredPointerV1.self,
                from: candidate.data
            )
            guard try Self.canonicalData(currentValue) == current.data,
                  try Self.canonicalData(candidateValue) == candidate.data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try StorePointerSchemaRegistry.requireRetired(
                currentValue.schemaVersion
            )
            try StorePointerSchemaRegistry.requireRetired(
                candidateValue.schemaVersion
            )
        default:
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard current.identity.linkCount == 1,
              candidate.identity.linkCount == 1,
              try Self.regularFileIdentity(
                  parent: dataDescriptor,
                  name: name
              ) == current.identity,
              try Self.regularFileIdentity(
                  parent: dataDescriptor,
                  name: temporary
              ) == candidate.identity,
              Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
              Darwin.fsync(dataDescriptor) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent(name, isDirectory: false)
        )
    }

    private func replacePointer<Value: Encodable>(
        name: String,
        value: Value,
        expectedData requiredExpectedData: Data? = nil
    ) throws {
        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        try verify()
        try enforce(
            .generationPointer,
            at: dataURL.appendingPathComponent(name, isDirectory: false)
        )
        let expectedRead = try Self.readRegularFileWithIdentity(
            parent: dataDescriptor,
            name: name
        )
        let expectedIdentity = expectedRead.identity
        let expected = expectedRead.data
        if let requiredExpectedData,
           expected != requiredExpectedData {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let replacement = try Self.canonicalData(value)
        let temporary = ".\(name).restore-next"
        if try Self.itemExists(parent: dataDescriptor, name: temporary) {
            try enforce(
                .generationPointerTemporary,
                at: dataURL.appendingPathComponent(temporary, isDirectory: false)
            )
            let existingTemporary = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: temporary
            )
            let existingCurrent = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            guard existingTemporary.data == replacement,
                  existingTemporary.identity.linkCount == 1,
                  existingCurrent.data == expected,
                  existingCurrent.identity == expectedIdentity,
                  Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
        }
        try Self.createRegularFile(
            parent: dataDescriptor,
            name: temporary,
            data: replacement
        )
        try enforce(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(temporary, isDirectory: false)
        )
        let replacementIdentity = try Self.regularFileIdentity(
            parent: dataDescriptor,
            name: temporary
        )
        var published = false
        let publishedIdentity = replacementIdentity
        do {
            try verify()
            let currentBeforeSwap = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            guard currentBeforeSwap.identity == expectedIdentity,
                  currentBeforeSwap.data == expected,
                  Darwin.renameatx_np(
                      dataDescriptor,
                      temporary,
                      dataDescriptor,
                      name,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            published = true
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verify()
            try enforce(
                .generationPointer,
                at: dataURL.appendingPathComponent(name, isDirectory: false)
            )
            let currentAfterSwap = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            let oldTemporary = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: temporary
            )
            guard currentAfterSwap.data == replacement,
                  currentAfterSwap.identity == replacementIdentity,
                  oldTemporary.data == expected,
                  oldTemporary.identity == expectedIdentity,
                  Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } catch {
            if published,
               let current = try? Self.readRegularFileWithIdentity(
                   parent: dataDescriptor,
                   name: name
               ),
               current.data == replacement,
               current.identity == publishedIdentity {
                do {
                    let oldTemporary = try Self.readRegularFileWithIdentity(
                        parent: dataDescriptor,
                        name: temporary
                    )
                    guard oldTemporary.data == expected,
                          oldTemporary.identity == expectedIdentity,
                          Darwin.renameatx_np(
                              dataDescriptor,
                              name,
                              dataDescriptor,
                              temporary,
                              UInt32(RENAME_SWAP)
                          ) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    try verify()
                    try enforce(
                        .generationPointer,
                        at: dataURL.appendingPathComponent(name, isDirectory: false)
                    )
                    let restored = try Self.readRegularFileWithIdentity(
                        parent: dataDescriptor,
                        name: name
                    )
                    let replacementTemporary = try Self.readRegularFileWithIdentity(
                        parent: dataDescriptor,
                        name: temporary
                    )
                    guard restored.data == expected,
                          restored.identity == expectedIdentity,
                          replacementTemporary.data == replacement,
                          replacementTemporary.identity == replacementIdentity,
                          Darwin.unlinkat(dataDescriptor, temporary, 0) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } catch {
                    if ProtectedFilePolicyV1.isProtectedDataUnavailable(error) {
                        throw error
                    }
                }
            }
            if let temporaryData = try? Self.readRegularFile(
                parent: dataDescriptor,
                name: temporary
            ), temporaryData == replacement {
                _ = Darwin.unlinkat(dataDescriptor, temporary, 0)
                _ = Darwin.fsync(dataDescriptor)
            }
            throw error
        }
    }

    private func restorePointer(
        name: String,
        data: Data,
        expectedCurrentIdentity: RegularFileIdentity? = nil
    ) throws {
        let rollback = ".\(name).restore-rollback"
        let replacedIdentity = try Self.regularFileIdentity(
            parent: dataDescriptor,
            name: name
        )
        if let expectedCurrentIdentity {
            guard replacedIdentity == expectedCurrentIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        if try Self.itemExists(parent: dataDescriptor, name: rollback) {
            guard try Self.readRegularFile(parent: dataDescriptor, name: rollback)
                    == data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            guard Darwin.unlinkat(dataDescriptor, rollback, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try Self.createRegularFile(
            parent: dataDescriptor,
            name: rollback,
            data: data
        )
        try enforce(
            .generationPointerTemporary,
            at: dataURL.appendingPathComponent(rollback, isDirectory: false)
        )
        let publishedIdentity = try Self.regularFileIdentity(
            parent: dataDescriptor,
            name: rollback
        )
        var swapped = false
        do {
            guard try Self.regularFileIdentity(
                      parent: dataDescriptor,
                      name: name
                  ) == replacedIdentity,
                  Darwin.renameatx_np(
                      dataDescriptor,
                      rollback,
                      dataDescriptor,
                      name,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            swapped = true
            guard Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try enforce(
                .generationPointer,
                at: dataURL.appendingPathComponent(name, isDirectory: false)
            )
            let restored = try Self.readRegularFileWithIdentity(
                parent: dataDescriptor,
                name: name
            )
            let replaced = try Self.regularFileIdentity(
                parent: dataDescriptor,
                name: rollback
            )
            guard restored.data == data,
                  restored.identity == publishedIdentity,
                  replaced == replacedIdentity,
                  Darwin.unlinkat(dataDescriptor, rollback, 0) == 0,
                  Darwin.fsync(dataDescriptor) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            swapped = false
        } catch {
            if swapped,
               let currentIdentity = try? Self.regularFileIdentity(
                   parent: dataDescriptor,
                   name: name
               ),
               currentIdentity == publishedIdentity,
               let rollbackIdentity = try? Self.regularFileIdentity(
                   parent: dataDescriptor,
                   name: rollback
               ),
               rollbackIdentity == replacedIdentity {
                do {
                    guard Darwin.renameatx_np(
                              dataDescriptor,
                              name,
                              dataDescriptor,
                              rollback,
                              UInt32(RENAME_SWAP)
                          ) == 0,
                          Darwin.fsync(dataDescriptor) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } catch {
                    if ProtectedFilePolicyV1.isProtectedDataUnavailable(error) {
                        throw error
                    }
                }
            }
            throw error
        }
    }

    private func tree(parent: Int32, id: UUID) throws -> Tree {
        try verify()
        let name = Self.canonical(id)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let inventory = try GenerationInventory(parent: descriptor, requireModel: false, partialCleanup: true)
        try inventory.revalidate()
        try verify()
        guard try Self.requiredDirectoryIdentity(parent: parent, name: name) == inventory.root.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return inventory.tree
    }

    private enum DirectoryCleanupOwnership { case generation, importStaging }

    private func removeDirectory(parent: Int32, name: String, ownership: DirectoryCleanupOwnership, expectedRoot: Identity? = nil) throws {
        try Self.requireSafeBasename(name)
        try verify()
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        if descriptor < 0, errno == ENOENT { return }
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let expected = try Self.identity(descriptor)
        guard expectedRoot == nil || expectedRoot == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch ownership {
        case .generation:
            try Self.removeContents(of: descriptor, authorityCheck: {
                try self.verify()
                guard try Self.requiredDirectoryIdentity(parent: parent, name: name) == expected else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            })
        case .importStaging:
            // Import packages have their own record/member authority, not the
            // installed-generation filename grammar.
            try Self.removeImportContents(of: descriptor)
        }
        try verify()
        guard try Self.requiredDirectoryIdentity(parent: parent, name: name) == expected,
              Darwin.unlinkat(parent, name, AT_REMOVEDIR) == 0,
              Darwin.fsync(parent) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try verify()
        guard try !Self.itemExists(parent: parent, name: name) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    fileprivate static func removeContents(of directory: Int32, authorityCheck: () throws -> Void = {}) throws {
        let inventory = try GenerationInventory(parent: directory, requireModel: false, partialCleanup: true)
        try inventory.removeAll(authorityCheck: authorityCheck)
    }

    private static func removeImportContents(of directory: Int32) throws {
        for name in try names(in: directory) {
            var info = stat()
            guard Darwin.fstatat(
                directory,
                name,
                &info,
                AT_SYMLINK_NOFOLLOW
            ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            switch info.st_mode & S_IFMT {
            case S_IFDIR:
                let child = Darwin.openat(
                    directory,
                    name,
                    O_RDONLY | O_DIRECTORY | O_NOFOLLOW
                )
                guard child >= 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let expected: Identity
                do {
                    expected = try identity(child)
                    try removeImportContents(of: child)
                } catch {
                    _ = Darwin.close(child)
                    throw error
                }
                _ = Darwin.close(child)
                guard try requiredDirectoryIdentity(parent: directory, name: name)
                        == expected,
                      Darwin.unlinkat(directory, name, AT_REMOVEDIR) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            case S_IFREG:
                guard info.st_nlink == 1,
                      Darwin.unlinkat(directory, name, 0) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            default:
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard Darwin.fsync(directory) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }



    static func names(in descriptor: Int32) throws -> [String] {
        let independent = Darwin.openat(
            descriptor,
            ".",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard independent >= 0, let directory = Darwin.fdopendir(independent) else {
            if independent >= 0 { _ = Darwin.close(independent) }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.closedir(directory) }
        var result = [String]()
        errno = 0
        while let entry = Darwin.readdir(directory) {
            guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if name != "." && name != ".." { result.append(name) }
            errno = 0
        }
        guard errno == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        return result.sorted()
    }

    fileprivate static func itemExists(parent: Int32, name: String) throws -> Bool {
        try requireSafeBasename(name)
        var info = stat()
        if Darwin.fstatat(parent, name, &info, AT_SYMLINK_NOFOLLOW) == 0 {
            return true
        }
        guard errno == ENOENT else { throw StoreGenerationFailure.dataPointerInvalid }
        return false
    }

    private static func directoryPresence(parent: Int32, name: String) throws -> Bool {
        var info = stat()
        if Darwin.fstatat(parent, name, &info, AT_SYMLINK_NOFOLLOW) != 0 {
            guard errno == ENOENT else { throw StoreGenerationFailure.dataPointerInvalid }
            return false
        }
        guard (info.st_mode & S_IFMT) == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return true
    }

    fileprivate static func requiredDirectoryIdentity(
        parent: Int32,
        name: String
    ) throws -> Identity {
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        return try identity(descriptor)
    }

    private static func openDirectory(parent: Int32, name: String) throws -> Int32 {
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        return descriptor
    }

    private static func openOrCreateDirectory(parent: Int32, name: String) throws -> Int32 {
        var descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        if descriptor < 0, errno == ENOENT {
            guard Darwin.mkdirat(parent, name, mode_t(0o700)) == 0 || errno == EEXIST,
                  Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            descriptor = Darwin.openat(
                parent,
                name,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
        }
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        return descriptor
    }

    private static func regularFileSnapshot(
        descriptor: Int32,
        mismatchReason: StoreMigrationMaintenanceReasonV1
    ) throws -> RegularFileSnapshot {
        var information = stat()
        guard Darwin.fstat(descriptor, &information) == 0,
              (information.st_mode & S_IFMT) == S_IFREG,
              information.st_nlink == 1,
              information.st_size >= 0,
              information.st_size <= off_t(Int.max) else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        return RegularFileSnapshot(
            device: information.st_dev,
            inode: information.st_ino,
            linkCount: information.st_nlink,
            type: information.st_mode & S_IFMT,
            byteCount: information.st_size,
            modificationSeconds: Int64(information.st_mtimespec.tv_sec),
            modificationNanoseconds: Int64(information.st_mtimespec.tv_nsec),
            statusChangeSeconds: Int64(information.st_ctimespec.tv_sec),
            statusChangeNanoseconds: Int64(information.st_ctimespec.tv_nsec)
        )
    }

    private static func namedRegularFileSnapshot(
        parent: Int32,
        name: String,
        mismatchReason: StoreMigrationMaintenanceReasonV1
    ) throws -> RegularFileSnapshot {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        defer { _ = Darwin.close(descriptor) }
        return try regularFileSnapshot(
            descriptor: descriptor,
            mismatchReason: mismatchReason
        )
    }

    private static func streamedDigest(
        descriptor: Int32,
        expectedSnapshot: RegularFileSnapshot,
        mismatchReason: StoreMigrationMaintenanceReasonV1,
        cancellationCheck: () throws -> Void = {}
    ) throws -> StreamedFileDigest {
        try cancellationCheck()
        guard Darwin.lseek(descriptor, 0, SEEK_SET) == 0 else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        var hasher = SHA256()
        var byteCount = 0
        var buffer = [UInt8](
            repeating: 0,
            count: migrationStreamBufferByteCount
        )
        while true {
            try cancellationCheck()
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count == 0 { break }
            guard count > 0 else {
                if errno == EINTR { continue }
                throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
            }
            let (nextCount, overflow) = byteCount.addingReportingOverflow(count)
            guard !overflow, off_t(nextCount) <= expectedSnapshot.byteCount else {
                throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
            }
            byteCount = nextCount
            hasher.update(data: Data(buffer.prefix(count)))
            try cancellationCheck()
        }
        guard byteCount == Int(expectedSnapshot.byteCount),
              try regularFileSnapshot(
                  descriptor: descriptor,
                  mismatchReason: mismatchReason
              ) == expectedSnapshot else {
            throw StoreMigrationFailure.maintenanceRequired(mismatchReason)
        }
        return StreamedFileDigest(
            byteCount: byteCount,
            sha256: hexDigest(hasher.finalize()),
            snapshot: expectedSnapshot
        )
    }

    private static func hexDigest(_ digest: SHA256.Digest) -> String {
        digest.map { String(format: "%02x", $0) }.joined()
    }

    fileprivate static func readRegularFileWithIdentity(
        parent: Int32,
        name: String
    ) throws -> RegularFileRead {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG,
              before.st_nlink == 1,
              before.st_size >= 0,
              before.st_size <= off_t(Self.maximumControlFileByteCount) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var data = Data()
        var buffer = [UInt8](repeating: 0, count: 16 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count > 0 {
                data.append(contentsOf: buffer.prefix(count))
            } else if count == 0 {
                break
            } else if errno != EINTR {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              (after.st_mode & S_IFMT) == S_IFREG,
              after.st_nlink == 1,
              before.st_dev == after.st_dev,
              before.st_ino == after.st_ino,
              before.st_size == after.st_size,
              data.count == Int(after.st_size) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RegularFileRead(
            data: data,
            identity: RegularFileIdentity(
                device: after.st_dev,
                inode: after.st_ino,
                linkCount: after.st_nlink
            )
        )
    }

    fileprivate static func readRegularFile(
        parent: Int32,
        name: String
    ) throws -> Data {
        try readRegularFileWithIdentity(parent: parent, name: name).data
    }

    fileprivate static func createRegularFile(
        parent: Int32,
        name: String,
        data: Data
    ) throws {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(
            parent,
            name,
            O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
            mode_t(0o600)
        )
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        do {
            try data.withUnsafeBytes { raw in
                guard let base = raw.baseAddress else { return }
                var offset = 0
                while offset < raw.count {
                    let count = Darwin.write(
                        descriptor,
                        base.advanced(by: offset),
                        raw.count - offset
                    )
                    if count > 0 {
                        offset += count
                    } else if errno != EINTR {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
            guard Darwin.fsync(descriptor) == 0,
                  Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } catch {
            _ = Darwin.unlinkat(parent, name, 0)
            _ = Darwin.fsync(parent)
            throw error
        }
    }

    private static func canonicalData<Value: Encodable>(_ value: Value) throws -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        return try encoder.encode(value)
    }

    private static func decodeCanonicalPointer<Value: Codable>(
        _ data: Data
    ) throws -> Value {
        do {
            let value = try JSONDecoder().decode(Value.self, from: data)
            guard try canonicalData(value) == data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return value
        } catch let error as StoreGenerationFailure {
            throw error
        } catch {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    fileprivate static func decodeCanonicalPointer<Value: Codable>(
        parent: Int32,
        name: String
    ) throws -> Value {
        let captured = try readRegularFileWithIdentity(parent: parent, name: name)
        let value: Value = try decodeCanonicalPointer(captured.data)
        guard try regularFileIdentity(parent: parent, name: name) == captured.identity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return value
    }

    private static func identity(_ descriptor: Int32) throws -> Identity {
        var info = stat()
        guard Darwin.fstat(descriptor, &info) == 0,
              (info.st_mode & S_IFMT) == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return Identity(device: info.st_dev, inode: info.st_ino)
    }

    fileprivate static func regularFileIdentity(
        parent: Int32,
        name: String
    ) throws -> RegularFileIdentity {
        try requireSafeBasename(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }

        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG,
              before.st_nlink == 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              (after.st_mode & S_IFMT) == S_IFREG,
              after.st_nlink == 1,
              before.st_dev == after.st_dev,
              before.st_ino == after.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RegularFileIdentity(
            device: after.st_dev,
            inode: after.st_ino,
            linkCount: after.st_nlink
        )
    }

    fileprivate static func regularFileIdentity(
        descriptor: Int32
    ) throws -> RegularFileIdentity {
        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              (before.st_mode & S_IFMT) == S_IFREG,
              before.st_nlink == 1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              (after.st_mode & S_IFMT) == S_IFREG,
              after.st_nlink == 1,
              before.st_dev == after.st_dev,
              before.st_ino == after.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RegularFileIdentity(
            device: after.st_dev,
            inode: after.st_ino,
            linkCount: after.st_nlink
        )
    }

    fileprivate static func regularFileIdentity(
        at url: URL
    ) throws -> RegularFileIdentity {
        let descriptor = Darwin.open(url.standardizedFileURL.path, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        return try regularFileIdentity(descriptor: descriptor)
    }

    fileprivate static func directoryIdentity(
        at url: URL
    ) throws -> Identity {
        let descriptor = Darwin.open(
            url.standardizedFileURL.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        defer { _ = Darwin.close(descriptor) }
        return try identity(descriptor)
    }

    fileprivate static func directoryIdentity(
        descriptor: Int32
    ) throws -> Identity {
        try identity(descriptor)
    }

    private static func require(_ descriptor: Int32, _ expected: Identity) throws {
        guard try identity(descriptor) == expected else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private static func currentURL(for descriptor: Int32) throws -> URL {
        var path = [CChar](repeating: 0, count: Int(MAXPATHLEN))
        let result = Darwin.fcntl(descriptor, F_GETPATH, &path)
        guard result >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let value = String(cString: path)
        guard !value.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return URL(fileURLWithPath: value, isDirectory: true)
            .standardizedFileURL
    }

    private static func canonical(_ id: UUID) -> String {
        id.uuidString.lowercased()
    }

    private static func idOrder(_ lhs: UUID, _ rhs: UUID) -> Bool {
        canonical(lhs) < canonical(rhs)
    }
}

enum StoreGenerationPruneFaultBoundaryV1: String, CaseIterable, Equatable, Sendable {
    case prepared
    case bytesRemoved
    case retiredPointerPublished
    case receiptPublished
}

#if DEBUG
enum StoreGenerationPruneInjectedFailureV1: Error, Equatable {
    case injectedFault(StoreGenerationPruneFaultBoundaryV1)
}

final class StoreGenerationPruneFailureInjectionV1 {
    private var pending: StoreGenerationPruneFaultBoundaryV1?

    init(failOnceAt boundary: StoreGenerationPruneFaultBoundaryV1) {
        self.pending = boundary
    }

    func reach(_ boundary: StoreGenerationPruneFaultBoundaryV1) throws {
        guard pending == boundary else { return }
        pending = nil
        throw StoreGenerationPruneInjectedFailureV1.injectedFault(boundary)
    }
}
#endif

struct StoreGenerationFactory {
    @MainActor private static var aggregateSourceDrains: [UUID: StoreMigrationSourceDrainProofV1] = [:]
    @MainActor private static var runningAggregateRecoveries: Set<UUID> = []
    private static let dataDirectoryName = "FieldEvidenceData"
    private static let bootstrapDirectoryName = ".FieldEvidenceData.bootstrap"
    private static let generationsDirectoryName = "generations"
    private static let currentPointerName = "current.json"
    private static let retiredPointerName = "retired.json"
    private static let modelStoreName = "model.sqlite"
    private static let bootstrapManifestMigrationID = UUID(
        uuidString: "00000000-0000-0000-0000-000000000003"
    )!
    private static let bootstrapPredecessorGenerationID = UUID(
        uuidString: "00000000-0000-0000-0000-000000000001"
    )!
    private static let pointerMutationLock = NSLock()

    private let applicationSupportURL: URL
    private let fileManager: FileManager
    private let migrationIdentitySource: StoreMigrationIdentitySourceV1?
    private let pointerEnrichmentIdentity: WorkspaceReplicaIdentityV1
    private let generationLeaseRegistryProvider: StoreGenerationLeaseRegistryProvider
    // Opt-in operation ownership. Ordinary factory behavior is unchanged.
    // The Erase operation, not this value or its save callback, must retain the
    // inventory until every captured lease has explicitly settled.
    private var eraseReaderRetirementInventory: EraseReaderRetirementInventoryV1? = nil

    func sharesRegistryProvider(with other: StoreGenerationFactory) -> Bool {
        generationLeaseRegistryProvider === other.generationLeaseRegistryProvider
            && applicationSupportURL.standardizedFileURL == other.applicationSupportURL.standardizedFileURL
    }

    /// Explicit single-use adoption after actual namespace/EX/descriptor
    /// retirement. This is never an exception-based cache refresh.
    @MainActor
    func freshForEraseAdoption(retirement: ErasedRegistryRetirementProofV1) throws -> Self {
        guard applicationSupportURL.standardizedFileURL == retirement.binding.subject.applicationSupportURL else {
            throw EraseAllServiceError.invalidAuthority
        }
        try retirement.consumeFreshFactoryCreation()
        return StoreGenerationFactory(copyingConfiguration: self)
    }

    private init(copyingConfiguration source: StoreGenerationFactory) {
        applicationSupportURL = source.applicationSupportURL
        fileManager = source.fileManager
        migrationIdentitySource = source.migrationIdentitySource
        pointerEnrichmentIdentity = source.pointerEnrichmentIdentity
        generationLeaseRegistryProvider = StoreGenerationLeaseRegistryProvider()
#if DEBUG
        migrationFailureInjection = source.migrationFailureInjection
        pruneFailureInjection = source.pruneFailureInjection
        coldOpenDiagnosticForTesting = source.coldOpenDiagnosticForTesting
#endif
    }

    /// Fixed fresh-writer construction uses ordinary future session behavior,
    /// with the identical provider and configuration. Existing captures stay
    /// retained by the adoption owner; no provider or identity is refreshed.
    @MainActor
    func ordinaryViewForEraseFreshWriter(adoption: EraseFreshAdoptionOwnerV1) throws -> Self {
        guard let inventory = eraseReaderRetirementInventory else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try adoption.requireOrdinaryFactoryView(factory: self, inventory: inventory)
        var ordinary = self
        ordinary.eraseReaderRetirementInventory = nil
        return ordinary
    }

    @MainActor
    func ordinaryViewForErasePreparation(operation: EraseRouterOperationV1,
        session: StoreGenerationSession, coordinator: StoreSessionCoordinator) throws -> Self {
        guard eraseReaderRetirementInventory === operation.inventory else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requirePreparationWriterConstruction(session: session, factory: self,
            coordinator: coordinator)
        var ordinary = self
        ordinary.eraseReaderRetirementInventory = nil
        return ordinary
    }

    @MainActor
    func ordinaryViewAfterEraseFreshFailure(adoption: EraseFreshAdoptionOwnerV1) throws -> Self {
        guard let inventory = eraseReaderRetirementInventory else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try adoption.requireDisposedFactoryView(factory: self, inventory: inventory)
        var ordinary = self
        ordinary.eraseReaderRetirementInventory = nil
        return ordinary
    }

    @MainActor
    func requireEraseReaderInventory(_ inventory: EraseReaderRetirementInventoryV1) throws {
        guard eraseReaderRetirementInventory === inventory else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    @MainActor
    func capturingEraseReaders(in inventory: EraseReaderRetirementInventoryV1) throws -> Self {
        try inventory.requireUnsealed()
        guard eraseReaderRetirementInventory == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var captured = self
        captured.eraseReaderRetirementInventory = inventory
        return captured
    }
#if DEBUG
    private let migrationFailureInjection: StoreMigrationFailureInjection?
    private let pruneFailureInjection: StoreGenerationPruneFailureInjectionV1?
    var coldOpenDiagnosticForTesting = false
#endif

    init(
        applicationSupportURL: URL,
        fileManager: FileManager = .default,
        migrationIdentitySource: StoreMigrationIdentitySourceV1? = nil,
        pointerEnrichmentIdentity: WorkspaceReplicaIdentityV1? = nil
    ) {
        self.applicationSupportURL = applicationSupportURL
        self.fileManager = fileManager
        self.migrationIdentitySource = migrationIdentitySource
        self.pointerEnrichmentIdentity = pointerEnrichmentIdentity
            ?? Self.makeLiveWorkspaceIdentity()
        self.generationLeaseRegistryProvider = StoreGenerationLeaseRegistryProvider()
        #if DEBUG
        self.migrationFailureInjection = nil
        self.pruneFailureInjection = nil
        #endif
    }

#if DEBUG
    init(
        applicationSupportURL: URL,
        fileManager: FileManager = .default,
        migrationIdentitySource: StoreMigrationIdentitySourceV1? = nil,
        pointerEnrichmentIdentity: WorkspaceReplicaIdentityV1? = nil,
        migrationFailureInjection: StoreMigrationFailureInjection
    ) {
        self.applicationSupportURL = applicationSupportURL
        self.fileManager = fileManager
        self.migrationIdentitySource = migrationIdentitySource
        self.pointerEnrichmentIdentity = pointerEnrichmentIdentity
            ?? Self.makeLiveWorkspaceIdentity()
        self.generationLeaseRegistryProvider = StoreGenerationLeaseRegistryProvider()
        self.migrationFailureInjection = migrationFailureInjection
        self.pruneFailureInjection = nil
    }

    init(
        applicationSupportURL: URL,
        fileManager: FileManager = .default,
        migrationIdentitySource: StoreMigrationIdentitySourceV1? = nil,
        pointerEnrichmentIdentity: WorkspaceReplicaIdentityV1? = nil,
        pruneFailureInjection: StoreGenerationPruneFailureInjectionV1
    ) {
        self.applicationSupportURL = applicationSupportURL
        self.fileManager = fileManager
        self.migrationIdentitySource = migrationIdentitySource
        self.pointerEnrichmentIdentity = pointerEnrichmentIdentity
            ?? Self.makeLiveWorkspaceIdentity()
        self.generationLeaseRegistryProvider = StoreGenerationLeaseRegistryProvider()
        self.migrationFailureInjection = nil
        self.pruneFailureInjection = pruneFailureInjection
    }
#endif

    private static func makeLiveWorkspaceIdentity() -> WorkspaceReplicaIdentityV1 {
        for _ in 0..<16 {
            let workspaceID = WorkspaceID()
            let replicaID = ReplicaID()
            if let identity = try? WorkspaceReplicaIdentityV1(
                workspaceID: workspaceID,
                replicaID: replicaID
            ) {
                return identity
            }
        }
        preconditionFailure("Unable to create distinct workspace and replica identities")
    }

    private func forSaveReproof() -> StoreGenerationFactory {
        // The fixed closure below only reproves this session's generation.
        // Allocation ownership stays with the actual operation inventory;
        // saving must not extend that inventory's lifetime through a factory.
        var reproof = withoutColdOpenDiagnostics()
        reproof.eraseReaderRetirementInventory = nil
        return reproof
    }

    private func withoutColdOpenDiagnostics() -> StoreGenerationFactory {
#if DEBUG
        var copy = self
        copy.coldOpenDiagnosticForTesting = false
        return copy
#else
        return self
#endif
    }

#if DEBUG
    private func coldOpenDiagnostic(_ phase: String) {
        guard coldOpenDiagnosticForTesting else { return }
        let uptime = String(format: "%.6f", ProcessInfo.processInfo.systemUptime)
        FileHandle.standardError.write(Data(
            ("StoreGenerationFactory cold-open phase=" + phase
                + " uptimeSeconds=" + uptime + "\n").utf8
        ))
    }
#endif

    @MainActor
    private func reachMigrationBoundary(
        _ boundary: StoreMigrationFaultBoundaryV1
    ) throws {
#if DEBUG
        try migrationFailureInjection?.reach(boundary)
#else
        _ = boundary
#endif
    }

    private func reachPruneBoundary(
        _ boundary: StoreGenerationPruneFaultBoundaryV1
    ) throws {
#if DEBUG
        try pruneFailureInjection?.reach(boundary)
#else
        _ = boundary
#endif
    }

    var restoreApplicationSupportURL: URL {
        applicationSupportURL
    }

    func makeGenerationLeaseRegistry() throws -> GenerationLeaseRegistryV1 {
        try generationLeaseRegistryProvider.registry(
            applicationSupportURL: applicationSupportURL
        )
    }

    func makeGenerationLeaseRegistry(
        ownerID: UUID
    ) throws -> GenerationLeaseRegistryV1 {
        try GenerationLeaseRegistryV1(
            applicationSupportURL: applicationSupportURL,
            ownerID: ownerID
        )
    }

    @MainActor
    func currentGenerationEpoch() throws -> GenerationEpochV1 {
        // One restore authority (and so one root-protection proof) for this
        // read; currentGenerationPointerV3 still re-reads the pointer through it.
        let authority = try makeRestoreGenerationAuthority()
        let pointer = try currentGenerationPointerV3(
            expectedGenerationID: currentGenerationID(authority: authority),
            authority: authority
        )
        guard let generationID = canonicalUUID(from: pointer.generationID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try GenerationEpochV1(
            generationID: generationID,
            generationManifestSHA256: pointer.generationManifestSHA256
        )
    }

    @MainActor
    func makeWriterFence(
        expectedGenerationEpoch: GenerationEpochV1,
        writerLeaseToken: GenerationLeaseTokenV1,
        registry: GenerationLeaseRegistryV1
    ) throws -> StaleWriterFenceV1 {
        try StaleWriterFenceV1(
            expectedGenerationEpoch: expectedGenerationEpoch,
            writerLeaseToken: writerLeaseToken,
            registry: registry,
            currentGenerationEpoch: { [self] in
                try self.currentGenerationEpoch()
            }
        )
    }

    @MainActor
    private func acquireCurrentReaderLease(
        epoch: GenerationEpochV1,
        expectedPointerData: Data
    ) throws -> GenerationLeaseHandleV1 {
#if DEBUG
        coldOpenDiagnostic("current-reader-registry-before")
#endif
        let registry = try makeGenerationLeaseRegistry()
#if DEBUG
        coldOpenDiagnostic("current-reader-registry-after")
#endif
        try eraseReaderRetirementInventory?.registerFreshRegistry(registry, factory: self)
#if DEBUG
        coldOpenDiagnostic("current-reader-registration-after")
#endif
        return try registry.withNoMigrationReservation {
#if DEBUG
            coldOpenDiagnostic("current-reader-g-after")
#endif
            let current = try decodeCurrentPointer(
                at: dataRootURL.appendingPathComponent(Self.currentPointerName)
            )
            guard current.data == expectedPointerData else {
                throw GenerationLeaseRegistryFailureV1.staleGeneration
            }
            if let inventory = eraseReaderRetirementInventory {
                let allocation = try registry.makeReaderAllocationAttempt(epoch: epoch)
#if DEBUG
                coldOpenDiagnostic("current-reader-allocation-after")
#endif
                try inventory.retainAllocation(allocation)
#if DEBUG
                coldOpenDiagnostic("current-reader-retain-after")
#endif
                return try inventory.acquireCapturedReader(allocation)
            }
            return try registry.acquireHandle(epoch: epoch, role: .reader)
        }
    }

    @MainActor
    private func acquireAcceptedReaderLease(
        epoch: GenerationEpochV1
    ) throws -> GenerationLeaseHandleV1 {
        let registry = try makeGenerationLeaseRegistry()
        try eraseReaderRetirementInventory?.registerFreshRegistry(registry, factory: self)
        return try registry.withNoMigrationReservation {
            let authority = try makeRestoreGenerationAuthority()
            let acceptedIDs = try Set(
                [try authority.currentGenerationID()]
                    + authority.retiredGenerationIDs()
            )
            guard acceptedIDs.contains(epoch.generationID) else {
                throw GenerationLeaseRegistryFailureV1.staleGeneration
            }
            if let inventory = eraseReaderRetirementInventory {
                let allocation = try registry.makeReaderAllocationAttempt(epoch: epoch)
                try inventory.retainAllocation(allocation)
                return try inventory.acquireCapturedReader(allocation)
            }
            return try registry.acquireHandle(epoch: epoch, role: .reader)
        }
    }

    /// Capture while ordinary admission is still held, before transferred EX.
    /// Every legacy/v2/v3 validation branch remains the incumbent predicate.
    @MainActor
    func captureEraseCurrentManifest(binding: EraseRetirementBindingV1,
                                     authority: StoreRestoreGenerationAuthority) throws
        -> EraseCurrentManifestScopeV1 {
        guard applicationSupportURL.standardizedFileURL
                == binding.subject.applicationSupportURL.standardizedFileURL else {
            throw EraseAllServiceError.invalidAuthority
        }
        let current = try authority.currentGenerationID()
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName))
        guard current == binding.subject.newGenerationID,
              envelope.generationID == canonicalString(for: current) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let store: StoreMigrationJournalStoreV1?
        switch envelope {
        case .legacy:
            store = nil
        case .v2(let pointer, _):
            guard pointer.generationManifestSHA256 == binding.generationEpoch.generationManifestSHA256 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let retained = try StoreMigrationJournalStoreV1(applicationSupportURL: applicationSupportURL)
            _ = try requireCurrentManifest(pointer, retainedStore: retained)
            store = retained
        case .v3(let pointer, _):
            guard pointer.generationManifestSHA256 == binding.generationEpoch.generationManifestSHA256,
                  try pointer.identity() == binding.workspaceIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let retained = try StoreMigrationJournalStoreV1(applicationSupportURL: applicationSupportURL)
            _ = try requireCurrentManifest(pointer, retainedStore: retained)
            store = retained
        }
        // Creating the pre-transfer store must not have changed the bound
        // physical namespace. The EX owner revalidates again at transfer.
        var information = stat()
        let operations = applicationSupportURL.appendingPathComponent("FieldEvidenceOperations", isDirectory: true)
        guard Darwin.lstat(operations.path, &information) == 0,
              information.st_mode & S_IFMT == S_IFDIR,
              UInt64(bitPattern: Int64(information.st_dev)) == binding.registryIdentity.device,
              UInt64(information.st_ino) == binding.registryIdentity.inode else {
            throw EraseAllServiceError.invalidAuthority
        }
        return EraseCurrentManifestScopeV1(binding: binding, pointerData: envelope.data, store: store)
    }

    @MainActor
    func captureEraseTargetReader(session: StoreGenerationSession,
        inventory: EraseReaderRetirementInventoryV1, binding: EraseRetirementBindingV1)
        throws -> GenerationLeaseHandleV1 {
        guard eraseReaderRetirementInventory === inventory,
              session.generationID == binding.subject.newGenerationID,
              session.generationEpoch == binding.generationEpoch,
              session.workspaceIdentity == binding.workspaceIdentity,
              let reader = session.eraseRetirementReaderHandle else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try inventory.capture(session)
        return reader
    }

    @MainActor
    func preserveEraseManifest(scope: EraseCurrentManifestScopeV1,
        retirement: ErasedRegistryRetirementProofV1) throws {
        guard scope.binding == retirement.binding, let store = scope.store else {
            throw EraseAllServiceError.invalidAuthority
        }
        let attempt = try retirement.prepareManifestRetirement(using: store)
        try attempt.preserveAfterLeaseDrain(retirement: retirement)
    }

    @MainActor
    func retiredGenerationIDsForEraseRetirement(authority: StoreRestoreGenerationAuthority,
        retirement: ErasedRegistryRetirementProofV1) throws -> [UUID] {
        let bytes = try retirement.readPointer(using: authority, name: "retired.json")
        let pointer = try JSONDecoder().decode(RetiredPointerV1.self, from: bytes)
        guard try canonicalData(for: pointer) == bytes else { throw StoreGenerationFailure.dataPointerInvalid }
        try StorePointerSchemaRegistry.requireRetired(pointer.schemaVersion)
        let ids = pointer.generationIDs.compactMap { UUID(uuidString: $0) }
        guard ids.count == pointer.generationIDs.count,
              pointer.generationIDs == ids.map({ canonicalString(for: $0) }),
              pointer.generationIDs == pointer.generationIDs.sorted(),
              Set(ids).count == ids.count else { throw StoreGenerationFailure.dataPointerInvalid }
        return ids
    }

    /// Fixed noncreating current validation under the genuine retired-reader
    /// capability. No new registry or migration store is constructed here.
    @MainActor
    func currentGenerationIDForEraseRetirement(
        authority: StoreRestoreGenerationAuthority,
        retirement: ErasedRegistryRetirementProofV1,
        manifestScope: EraseCurrentManifestScopeV1
    ) throws -> UUID {
        try retirement.requireCurrentGenerationValidation()
        guard manifestScope.binding == retirement.binding,
              applicationSupportURL.standardizedFileURL
                == retirement.binding.subject.applicationSupportURL.standardizedFileURL else {
            throw EraseAllServiceError.invalidAuthority
        }
        let pointerData = try retirement.readPointer(using: authority, name: "current.json")
        let envelope = try CurrentPointerCodecV1.decode(pointerData)
        guard let current = UUID(uuidString: envelope.generationID),
              current == retirement.binding.subject.newGenerationID,
              envelope.data == manifestScope.pointerData,
              envelope.generationID == canonicalString(for: current) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch envelope {
        case .legacy:
            guard manifestScope.store == nil else { throw EraseAllServiceError.invalidAuthority }
        case .v2(let pointer, _):
            guard let store = manifestScope.store else { throw EraseAllServiceError.invalidAuthority }
            try pointer.validate()
            let manifest = try retirement.readCurrentManifest(using: store,
                generationID: current, expectedDigest: pointer.generationManifestSHA256)
            guard manifest.generationID == current, manifest.storeSchemaRelease == .v2 else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        case .v3(let pointer, _):
            guard let store = manifestScope.store else { throw EraseAllServiceError.invalidAuthority }
            try pointer.validate()
            let manifest = try retirement.readCurrentManifest(using: store,
                generationID: current, expectedDigest: pointer.generationManifestSHA256)
            guard let expectedRelease = PersistentSchemaReleaseRegistryV1.releases.first(where: {
                $0.versionIdentifier.major == pointer.storeSchemaVersion
            }) else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            guard manifest.generationID == current,
                  manifest.storeSchemaRelease == expectedRelease else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        try retirement.requireCurrentGenerationValidation()
        return current
    }

    @MainActor
    func currentGenerationID() throws -> UUID {
        let authority = try makeRestoreGenerationAuthority()
        return try currentGenerationID(authority: authority)
    }

    @MainActor
    func currentGenerationID(
        authority: StoreRestoreGenerationAuthority
    ) throws -> UUID {
        let authorityValue = try authority.currentGenerationID()
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        switch envelope {
        case .legacy(let pointer, _):
            guard canonicalUUID(from: pointer.generationID) == authorityValue else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        case .v2(let pointer, _):
            guard canonicalUUID(from: pointer.generationID) == authorityValue else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try requireCurrentManifest(pointer)
        case .v3(let pointer, _):
            guard canonicalUUID(from: pointer.generationID) == authorityValue else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = try requireCurrentManifest(pointer)
        }
        return authorityValue
    }

    @MainActor
    func currentWorkspaceIdentity(
        expectedGenerationID: UUID,
        authority suppliedAuthority: StoreRestoreGenerationAuthority? = nil
    ) throws -> WorkspaceReplicaIdentityV1 {
