    private func currentPointer(
        from identity: RestorePointerIdentityV1
    ) throws -> CurrentGenerationPointerV3 {
        try CurrentGenerationPointerV3(
            generationID: identity.generationID,
            generationManifestSHA256: identity.generationManifestSHA256,
            workspaceID: WorkspaceID(rawValue: identity.workspaceID),
            replicaID: ReplicaID(rawValue: identity.replicaID),
            knownReplicaIDs: Set(identity.knownReplicaIDs.map { ReplicaID(rawValue: $0) }),
            storeSchemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
        )
    }

    @MainActor
    private func requireCurrentPointer(
        _ identity: RestorePointerIdentityV1,
        authority: StoreRestoreGenerationAuthority
    ) throws -> CurrentGenerationPointerV3 {
        guard try authority.currentGenerationID() == identity.generationID,
              case .v3(let actual, let data) = try decodeCurrentPointer(
                at: dataRootURL.appendingPathComponent(Self.currentPointerName)
              ) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let expected = try currentPointer(from: identity)
        guard actual == expected,
              data == (try expected.canonicalData()) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        _ = try requireCurrentManifest(actual)
        return actual
    }

    private func restorePointerIdentity(
        _ pointer: CurrentGenerationPointerV3
    ) throws -> RestorePointerIdentityV1 {
        try pointer.validate()
        guard let generationID = canonicalUUID(from: pointer.generationID),
              let workspaceID = canonicalUUID(from: pointer.workspaceID),
              let replicaID = canonicalUUID(from: pointer.replicaID) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return RestorePointerIdentityV1(
            generationID: generationID,
            generationManifestSHA256: pointer.generationManifestSHA256,
            knownReplicaIDs: Set(try pointer.knownReplicaIdentitySet().map(\.rawValue)),
            workspaceID: workspaceID,
            replicaID: replicaID
        )
    }

    /// Creates only the sealed plan's destination reviews in an unpublished generation.
    /// No writer, journal or temporary capability leaves this synchronous scope.
    @MainActor
    func writeRestoreDestinationReviews(
        plan: RepetitiveCaptureRestoreReviewPlanV1,
        authority: StoreRestoreGenerationAuthority,
        clock: any ApplicationClock,
        idSource: any ApplicationIDSource,
        fileAuthority: any ApplicationFileAuthorityV1,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> (history: MutationHistorySnapshotV1, checkpoints: [FieldDraftCheckpointV1]) {
        diagnosticPhase?("reviews.lock.begin")
        return try authority.mutationRegistry.withNoMigrationReservation {
            diagnosticPhase?("reviews.lock.acquired")
            diagnosticPhase?("reviews.plan")
            try plan.validate()
            let target = plan.identity.targetPointer
            let identity = try WorkspaceReplicaIdentityV1(
                workspaceID: WorkspaceID(rawValue: target.workspaceID),
                replicaID: ReplicaID(rawValue: target.replicaID))
            diagnosticPhase?("reviews.manifest-store")
            let manifestStore = try StoreMigrationJournalStoreV1(
                applicationSupportURL: applicationSupportURL)
            @MainActor func requireUnpublished() throws {
                diagnosticPhase?("reviews.unpublished.root")
                try authority.requireRestoreReviewRoot(applicationSupportURL)
                diagnosticPhase?("reviews.unpublished.no-journal")
                try authority.requireNoRestoreJournal()
                diagnosticPhase?("reviews.unpublished.current-pointer")
                _ = try requireCurrentPointer(plan.identity.oldPointer, authority: authority)
                diagnosticPhase?("reviews.unpublished.presence")
                let presence = try authority.presence(id: target.generationID)
                diagnosticPhase?("reviews.unpublished.guards")
                guard presence.staging, !presence.installed,
                      target.generationID != plan.identity.oldPointer.generationID,
                      try manifestStore.loadManifestIfPresent(targetGenerationID: target.generationID) == nil,
                      try !authority.mutationRegistry.activeEpochs().contains(where: {
                          $0.generationID == target.generationID
                      }) else { throw WorkspaceMutationFailureV1.wrongGeneration }
                diagnosticPhase?("reviews.unpublished.staging")
                try authority.requireStagingGeneration(id: target.generationID)
            }
            try requireUnpublished()
            diagnosticPhase?("reviews.open-staging")
            let session = try openRestoreStagingGeneration(id: target.generationID,
                identity: identity, authority: authority, diagnosticPhase: diagnosticPhase)
            diagnosticPhase?("reviews.open-staging.end")
            let context = session.modelContext
            guard !context.hasChanges, session.workspaceIdentity == identity,
                  session.generationID == target.generationID,
                  session.generationEpoch == nil else {
                throw WorkspaceMutationFailureV1.wrongGeneration
            }
            diagnosticPhase?("reviews.root-identity")
            let rootIdentity = try authority.restoreReviewRootIdentity(id: target.generationID)
            diagnosticPhase?("reviews.mutations")
            let mutations: [FieldDraftMutationV1] = try plan.checkpoints.map { checkpoint in
                try FieldDraftMutationV1(workspaceID: checkpoint.workspaceID,
                    expectedRevision: 0,
                    expectedBaseCanonicalRevision: checkpoint.baseCanonicalRevision,
                    mutationID: checkpoint.mutationID, postImage: .createCheckpoint(checkpoint))
            }
            diagnosticPhase?("reviews.capability")
            let capability = StoreRestoreReviewWriteAuthorityV1(
                context: context, identity: identity, generationID: target.generationID,
                commands: mutations.map { WorkspaceCommandV1.applyFieldDraft($0) },
                validateBinding: {
                    try requireUnpublished()
                    guard session.modelContext === context,
                          session.workspaceIdentity == identity,
                          session.generationID == target.generationID,
                          try authority.restoreReviewRootIdentity(id: target.generationID) == rootIdentity else {
                        throw WorkspaceMutationFailureV1.wrongGeneration
                    }
                })
            defer {
                diagnosticPhase?("reviews.cleanup.begin")
                capability.revoke(); context.rollback()
                diagnosticPhase?("reviews.cleanup.end")
            }
            diagnosticPhase?("reviews.journal-init")
            let journal = try MutationJournalStoreV1(modelContext: context, identity: identity,
                generationID: target.generationID, restoreReviewAuthority: capability)
            diagnosticPhase?("reviews.original-history")
            let originalHistory = try journal.exportSnapshot()
            diagnosticPhase?("reviews.original-checkpoints")
            let originalCheckpoints = try context.fetch(FetchDescriptor<FieldDraftCheckpointRow>()).map { try $0.value() }
            diagnosticPhase?("reviews.original-history.end")
            let originalDraftIDs = Set(originalCheckpoints.map(\.draftID))
            let originalDraftRevisionIDs = Set(originalHistory.entityRevisions.filter {
                $0.identity.kind == .fieldDraftCheckpoint
            }.map { $0.identity.id })
            let originalMutationIDs = try Set(originalHistory.receipts.map {
                try MutationEnvelopeV1.decodeCanonical(from: $0.envelopeData).mutationID
            })
            guard Set(plan.checkpoints.map(\.draftID)).count == plan.checkpoints.count,
                  Set(mutations.map(\.mutationID)).count == mutations.count,
                  plan.checkpoints.allSatisfy({
                      !originalDraftIDs.contains($0.draftID) && !originalDraftRevisionIDs.contains($0.draftID)
                  }),
                  mutations.allSatisfy({ !originalMutationIDs.contains($0.mutationID) }) else {
                throw WorkspaceMutationFailureV1.invalidCommand
            }
            let initial = try WorkspaceRevisionV1(workspaceID: identity.workspaceID,
                generationID: target.generationID, revision: 0, entityRevisions: [])
            diagnosticPhase?("reviews.writer-init")
            let writer = try WorkspaceWriterV1(identity: identity, generationID: target.generationID,
                initialRevision: initial, clock: clock, idSource: idSource,
                fileAuthority: fileAuthority,
                adapter: WorkspaceWriterAdapterV1(modelContext: context,
                    generationRootURL: session.generationRootURL, expectedRootIdentity: rootIdentity),
                journalStore: journal)
            defer { writer.invalidate() }
            diagnosticPhase?("reviews.writer-init.end")
            var createdRecords: [MutationHistoryReceiptRecordV1] = []
            for mutation in mutations {
                diagnosticPhase?("reviews.current-revision")
                let current = try writer.currentRevision()
                diagnosticPhase?("reviews.request")
                let entities: [WorkspaceEntityRevisionV1] = try mutation.concurrencyIdentities.map {
                    WorkspaceEntityRevisionV1(identity: $0, revision: 0)
                }
                let expected = try WorkspaceExpectedRevisionV1(workspaceID: current.workspaceID,
                    generationID: current.generationID, writerInstanceID: current.writerInstanceID,
                    workspaceRevision: current.revision, entityRevisions: entities)
                let request = WorkspaceMutationRequestV1(mutationID: mutation.mutationID,
                    expectedRevision: expected, command: .applyFieldDraft(mutation))
                let envelope = try MutationEnvelopeV1(request: request, identity: identity)
                diagnosticPhase?("reviews.bind")
                try capability.bind(envelope: envelope)
                diagnosticPhase?("reviews.execute")
                _ = try writer.execute(request)
                diagnosticPhase?("reviews.reproof")
                try session.reproofAfterSave()
                diagnosticPhase?("reviews.receipt")
                guard !context.hasChanges, let receipt = try journal.receipt(mutationID: mutation.mutationID),
                      receipt.envelopeSHA256 == (try envelope.canonicalSHA256()) else {
                    throw WorkspaceMutationFailureV1.receiptHistoryCorrupt
                }
                let record = MutationHistoryReceiptRecordV1(envelopeData: try envelope.canonicalData(),
                    receiptData: try receipt.canonicalData(), reversalBasisData: nil, semanticReversalData: nil)
                createdRecords.append(record)
                diagnosticPhase?("reviews.finish")
                try capability.finish(envelope: envelope)
            }
            try requireUnpublished()
            diagnosticPhase?("reviews.final-history")
            let history = try journal.exportSnapshot()
            diagnosticPhase?("reviews.final-history.end")
            let addedRevisions: [MutationHistoryEntityRevisionV1] = try plan.checkpoints.map {
                MutationHistoryEntityRevisionV1(
                    identity: try WorkspaceEntityIdentityV1(kind: .fieldDraftCheckpoint, id: $0.draftID),
                    revision: $0.draftRevision)
            }
            let createdIDs = Set(mutations.map(\.mutationID))
            var retainedRecords: [MutationHistoryReceiptRecordV1] = []
            var newRecords: [MutationHistoryReceiptRecordV1] = []
            for record in history.receipts {
                let envelope = try MutationEnvelopeV1.decodeCanonical(from: record.envelopeData)
                if createdIDs.contains(envelope.mutationID) { newRecords.append(record) }
                else { retainedRecords.append(record) }
            }
            let newRevisionIDs = Set(addedRevisions.map(\.identity))
            let retainedRevisions = history.entityRevisions.filter { !newRevisionIDs.contains($0.identity) }
            let newRevisions = history.entityRevisions.filter { newRevisionIDs.contains($0.identity) }
            let count = UInt64(createdRecords.count)
            let revision = originalHistory.workspaceRevision.addingReportingOverflow(count)
            let sequence = originalHistory.lastLocalSequence.addingReportingOverflow(count)
            diagnosticPhase?("reviews.final-checkpoints")
            let checkpoints = try context.fetch(FetchDescriptor<FieldDraftCheckpointRow>()).map { try $0.value() }
            diagnosticPhase?("reviews.final-comparison")
            guard !context.hasChanges, !revision.overflow, !sequence.overflow,
                  history.workspaceRevision == revision.partialValue,
                  history.lastLocalSequence == sequence.partialValue,
                  history.entityRevisions.count == originalHistory.entityRevisions.count + addedRevisions.count,
                  retainedRevisions == originalHistory.entityRevisions,
                  newRevisions == addedRevisions.sorted(by: { $0.identity.stableKey < $1.identity.stableKey }),
                  history.receipts.count == originalHistory.receipts.count + createdRecords.count,
                  retainedRecords == originalHistory.receipts, newRecords == createdRecords,
                  history.quarantines == originalHistory.quarantines,
                  checkpoints.count == originalCheckpoints.count + plan.checkpoints.count,
                  Set(checkpoints) == Set(originalCheckpoints + plan.checkpoints) else {
                throw WorkspaceMutationFailureV1.receiptHistoryCorrupt
            }
            let createdCheckpoints = checkpoints.filter { !originalDraftIDs.contains($0.draftID) }
                .sorted { $0.draftID.uuidString < $1.draftID.uuidString }
            diagnosticPhase?("reviews.return")
            return (history, createdCheckpoints)
        }
    }

    @MainActor
    func prepareRestoreStagingGenerationManifest(
        expectedOldID: UUID,
        newID: UUID,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> String {
        diagnosticPhase?("recovery.manifest.lock.begin")
        return try authority.mutationRegistry.withNoMigrationReservation {
            diagnosticPhase?("recovery.manifest.lock.acquired")
            try authority.requireRestoreReviewRoot(applicationSupportURL)
            return try prepareRestoreStagingGenerationManifestLocked(expectedOldID: expectedOldID,
                newID: newID, restoreProof: restoreProof, restoreFileSnapshot: restoreFileSnapshot,
                authority: authority, diagnosticPhase: diagnosticPhase)
        }
    }

    @MainActor
    private func prepareRestoreStagingGenerationManifestLocked(
        expectedOldID: UUID,
        newID: UUID,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> String {
        guard try authority.currentGenerationID() == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try authority.requireStagingGeneration(id: newID)
        if let restoreProof {
            try restoreProof.validate()
            guard restoreProof.predecessorGenerationID == expectedOldID,
                  restoreProof.generationID == newID else {
                throw StoreMigrationFailure.invalidContract
            }
            guard restoreFileSnapshot?.staging == true else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        } else {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectStagingGeneration(id: newID)
        }
        diagnosticPhase?("recovery.manifest.preflight.end")
        let root = restoreStagingGenerationURL(id: newID)
        _ = try requireRestoreFileSnapshot(
            restoreFileSnapshot,
            generationID: restoreProof?.generationID,
            at: root,
            restoreProof: restoreProof
        )
        diagnosticPhase?("recovery.manifest.file-snapshot.end")
        let modelStoreURL = root.appendingPathComponent(Self.modelStoreName)
        let markerMigrationID = try autoreleasepool { () throws -> UUID in
            diagnosticPhase?("recovery.manifest.container.begin")
            let container = try makeV53Container(at: modelStoreURL, migrate: false)
            diagnosticPhase?("recovery.manifest.container.end")
            diagnosticPhase?("recovery.manifest.marker.begin")
            let marker = try requireV53Marker(
                in: container.mainContext,
                expectedMigrationID: nil
            )
            diagnosticPhase?("recovery.manifest.marker.end")
            guard let value = marker.migrationID else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            return value
        }
        diagnosticPhase?("recovery.manifest.container-scope.end")
        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        let digest: String
        diagnosticPhase?("recovery.manifest.load.begin")
        if let existing = try store.loadManifestIfPresent(targetGenerationID: newID) {
            diagnosticPhase?("recovery.manifest.existing-verify.begin")
            try requireRestoreManifestSnapshot(
                existing.manifest,
                expectedOldID: expectedOldID,
                generationID: newID,
                at: root,
                staging: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            diagnosticPhase?("recovery.manifest.existing-verify.end")
            digest = existing.digest
        } else {
            diagnosticPhase?("recovery.manifest.semantic.begin")
            let semanticSHA256: String = try framedSemanticDigest(
                at: modelStoreURL,
                release: PersistentSchemaReleaseRegistryV1.activeRelease
            )
            diagnosticPhase?("recovery.manifest.semantic.end")
            diagnosticPhase?("recovery.manifest.identity.begin")
            let identityDigest: String = try frozenIdentityDigest(
                for: root,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            diagnosticPhase?("recovery.manifest.identity.end")
            diagnosticPhase?("recovery.manifest.files.begin")
            let fileDigests: [StoreGenerationFileDigestV1] = try generationFileDigests(
                at: root,
                durable: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            diagnosticPhase?("recovery.manifest.files.end")
            diagnosticPhase?("recovery.manifest.construct.begin")
            let manifest = try StoreGenerationManifestV1(
                schemaVersion: 2,
                generationID: newID,
                predecessorGenerationID: expectedOldID,
                migrationID: markerMigrationID,
                storeSchemaRelease: PersistentSchemaReleaseRegistryV1.activeRelease,
                semanticSHA256: semanticSHA256,
                semanticDigestAlgorithm: .framedLayersV1,
                frozenIdentityDigest: identityDigest,
                files: fileDigests,
                restoreProof: restoreProof
            )
            diagnosticPhase?("recovery.manifest.construct.end")
            diagnosticPhase?("recovery.manifest.write.begin")
            digest = try store.writeManifest(manifest)
            diagnosticPhase?("recovery.manifest.write.end")
            diagnosticPhase?("recovery.manifest.new-verify.begin")
            try requireRestoreManifestSnapshot(
                manifest,
                expectedOldID: expectedOldID,
                generationID: newID,
                at: root,
                staging: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
        }
        guard try authority.currentGenerationID() == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try authority.requireStagingGeneration(id: newID)
        diagnosticPhase?("recovery.manifest.return")
        return digest
    }

    @MainActor
    func requireInstalledRestoreGenerationSnapshot(
        expectedOldID: UUID,
        generationID: UUID,
        expectedManifestDigest: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard StoreMigrationCanonicalJSONV1.isLowercaseSHA256(
            expectedManifestDigest
        ) else {
            throw StoreMigrationFailure.invalidDigest
        }
        try authority.requireInstalledGeneration(id: generationID)
        if restoreProof == nil {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectInstalledGeneration(id: generationID)
        } else {
            guard restoreFileSnapshot?.staging == false else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
        }
        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        let manifest = try store.loadManifest(
            targetGenerationID: generationID,
            expectedDigest: expectedManifestDigest
        )
        try requireRestoreManifestSnapshot(
            manifest,
            expectedOldID: expectedOldID,
            generationID: generationID,
            at: installedGenerationURL(id: generationID),
            staging: false,
            restoreProof: restoreProof,
            restoreFileSnapshot: restoreFileSnapshot
        )
        if restoreProof == nil {
            try authority.protectInstalledGeneration(id: generationID)
        } else {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: installedGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        }
        try authority.requireInstalledGeneration(id: generationID)
    }

    @MainActor
    func removePreparedRestoreGenerationManifestBeforeDiscard(
        expectedOldID: UUID,
        generationID: UUID,
        expectedDigest: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard generationID != expectedOldID,
              StoreMigrationCanonicalJSONV1.isLowercaseSHA256(expectedDigest),
              try currentGenerationID(authority: authority) == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let presence = try generationPresence(
            id: generationID,
            authority: authority
        )
        guard !(presence.staging && presence.installed) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let restoreProof {
            guard let restoreFileSnapshot,
                  restoreFileSnapshot.staging == presence.staging,
                  presence.staging || presence.installed else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: presence.staging
                    ? restoreStagingGenerationURL(id: generationID)
                    : installedGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        } else if presence.staging {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectStagingGeneration(id: generationID)
            try authority.requireStagingGeneration(id: generationID)
        } else if presence.installed {
            guard restoreFileSnapshot == nil else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            try authority.protectInstalledGeneration(id: generationID)
            try authority.requireInstalledGeneration(id: generationID)
        }

        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        if let existing = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) {
            guard existing.digest == expectedDigest,
                  existing.manifest.generationID == generationID,
                  presence.staging || presence.installed else {
                throw StoreMigrationFailure.digestMismatch
            }
            try requireRestoreManifestSnapshot(
                existing.manifest,
                expectedOldID: expectedOldID,
                generationID: generationID,
                at: presence.staging
                    ? restoreStagingGenerationURL(id: generationID)
                    : installedGenerationURL(id: generationID),
                staging: presence.staging,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
            try store.removeManifest(
                targetGenerationID: generationID,
                expectedDigest: expectedDigest
            )
        }

        if let _ = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        guard try currentGenerationID(authority: authority) == expectedOldID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let after = try generationPresence(
            id: generationID,
            authority: authority
        )
        guard after.staging == presence.staging,
              after.installed == presence.installed,
              !(after.staging && after.installed) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let restoreProof {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: after.staging
                    ? restoreStagingGenerationURL(id: generationID)
                    : installedGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        } else if after.staging {
            try authority.protectStagingGeneration(id: generationID)
            try authority.requireStagingGeneration(id: generationID)
        } else if after.installed {
            try authority.protectInstalledGeneration(id: generationID)
            try authority.requireInstalledGeneration(id: generationID)
        }
    }

    @MainActor
    func removePreparedRestoreStagingGenerationManifest(
        generationID: UUID,
        expectedDigest: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        guard StoreMigrationCanonicalJSONV1.isLowercaseSHA256(expectedDigest),
              try authority.currentGenerationID() != generationID,
              !(try generationPresence(
                  id: generationID,
                  authority: authority
              ).installed) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if let restoreProof {
            guard restoreFileSnapshot?.staging == true else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: restoreStagingGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        } else if restoreFileSnapshot != nil {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let store = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
        guard let existing = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) else {
            return
        }
        guard existing.digest == expectedDigest,
              existing.manifest.generationID == generationID,
              existing.manifest.restoreProof == restoreProof else {
            throw StoreMigrationFailure.digestMismatch
        }
        try store.removeManifest(
            targetGenerationID: generationID,
            expectedDigest: expectedDigest
        )
        if let _ = try store.loadManifestIfPresent(
            targetGenerationID: generationID
        ) {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        if let restoreProof {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: restoreStagingGenerationURL(id: generationID),
                restoreProof: restoreProof
            )
        }
    }

    func restoreStagingGenerationURL(id: UUID) -> URL {
        applicationSupportURL
            .appendingPathComponent("FieldEvidenceRestore", isDirectory: true)
            .appendingPathComponent("generations", isDirectory: true)
            .appendingPathComponent(canonicalString(for: id), isDirectory: true)
    }

    func installedGenerationURL(id: UUID) -> URL {
        generationsURL.appendingPathComponent(
            canonicalString(for: id),
            isDirectory: true
        )
    }

    func prepareRestoreGenerationFileSnapshot(
        generationID: UUID,
        staging: Bool,
        expectedRootIdentity: StreamingArchiveRootIdentityV1,
        restoreProof: StoreRestoreGenerationManifestProofV1
    ) async throws -> StoreRestoreGenerationFileSnapshotV1 {
        try Task.checkCancellation()
        try restoreProof.validate()
        guard restoreProof.generationID == generationID else {
            throw StoreMigrationFailure.invalidContract
        }
        let rootURL = (staging
            ? restoreStagingGenerationURL(id: generationID)
            : installedGenerationURL(id: generationID)).standardizedFileURL
        let task = Task.detached {
            try StoreRestoreGenerationAuthority.prepareRestoreGenerationFileSnapshot(
                generationID: generationID,
                staging: staging,
                rootURL: rootURL,
                expectedRootIdentity: expectedRootIdentity,
                restoreProof: restoreProof,
                cancellationCheck: { try Task.checkCancellation() }
            )
        }
        return try await withTaskCancellationHandler(
            operation: { try await task.value },
            onCancel: { task.cancel() }
        )
    }

    func makeRestoreGenerationAuthority(
        expectedApplicationSupportIdentity: StoreApplicationSupportIdentity? = nil
    ) throws -> StoreRestoreGenerationAuthority {
        try StoreRestoreGenerationAuthority(
            applicationSupportURL: applicationSupportURL,
            expectedApplicationSupportIdentity: expectedApplicationSupportIdentity,
            mutationRegistry: try makeGenerationLeaseRegistry()
        )
    }

    func generationPresence(
        id: UUID,
        authority: StoreRestoreGenerationAuthority
    ) throws -> StoreRestoreGenerationAuthority.Presence {
        try authority.presence(id: id)
    }

    @MainActor
    func createRestoreStagingGeneration(
        id: UUID,
        authority: StoreRestoreGenerationAuthority,
        recordsSchemaVersion: Int,
        sourceGenerationID: UUID?,
        archiveProvenanceSHA256: String,
        populate: (ModelContext) throws -> Void
    ) throws {
        // Every archive version through the existing V53 constructor has a
        // source container and a closed migration path below. Do not skip the
        // Round and later versions between evidence curation and V53.
        guard (1...LightingNightWorkflowBackupEnrollmentV1.recordsSchemaVersion)
                .contains(recordsSchemaVersion),
              CompatibilityCanonicalV1.validSHA256(archiveProvenanceSHA256),
              (recordsSchemaVersion >= 5) == (sourceGenerationID != nil) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let root = restoreStagingGenerationURL(id: id)
        do {
            try authority.createStagingGeneration(id: id)
            let modelURL = root.appendingPathComponent(Self.modelStoreName)
            if recordsSchemaVersion >= 9 {
                try autoreleasepool {
                    let container = try makeFreshRestoreSourceContainer(
                        at: modelURL,
                        recordsSchemaVersion: recordsSchemaVersion,
                        markerMigrationID: id
                    )
                    let context = container.mainContext
                    try populate(context)
                    if context.hasChanges { try context.save() }
                }
            } else if recordsSchemaVersion == 8 {
                try autoreleasepool {
                    let container = try makeFreshV9Container(at: modelURL, markerMigrationID: id)
                    let context = container.mainContext; try populate(context)
                    if context.hasChanges { try context.save() }
                    _ = try requireV9Marker(in: context, expectedMigrationID: id)
                }
            } else if recordsSchemaVersion == 7 {
                try autoreleasepool {
                    let container = try makeFreshV8Container(
                        at: modelURL,
                        markerMigrationID: id
                    )
                    let context = container.mainContext
                    try populate(context)
                    if context.hasChanges { try context.save() }
                    _ = try requireV8Marker(in: context, expectedMigrationID: id)
                }
            } else if recordsSchemaVersion == 6 {
                try autoreleasepool {
                    let container = try makeFreshV7Container(
                        at: modelURL,
                        markerMigrationID: id
                    )
                    let context = container.mainContext
                    try populate(context)
                    if context.hasChanges {
                        try context.save()
                        guard !context.hasChanges else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    _ = try requireV7Marker(in: context, expectedMigrationID: id)
                }
            } else {
                try autoreleasepool {
                    let container = try makeFreshV6Container(
                        at: modelURL,
                        markerMigrationID: id
                    )
                    let context = container.mainContext
                    try populate(context)
                    if context.hasChanges {
                        try context.save()
                        guard !context.hasChanges else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                    if recordsSchemaVersion <= 4 {
                        try backfillLegacyRestoreV6LocationBaseline(
                            in: context,
                            migrationID: id,
                            archivalSourceGenerationID: try archivalSourceGenerationID(
                                archiveProvenanceSHA256: archiveProvenanceSHA256,
                                targetGenerationID: id
                            ),
                            targetGenerationID: id
                        )
                    } else {
                        guard let sourceGenerationID,
                              sourceGenerationID != id else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        _ = try requireV6Marker(in: context, expectedMigrationID: id)
                    }
                }
                try autoreleasepool {
                    let container = try makeV7Container(at: modelURL, migrate: true)
                    try backfillV7Marker(in: container.mainContext, migrationID: id)
                }
            }
            if recordsSchemaVersion < 7 {
                try autoreleasepool {
                    let container = try makeV8Container(at: modelURL, migrate: true)
                    let context = container.mainContext
                    let workspaceID = try restoreBackfillWorkspaceID(
                        in: context,
                        fallback: id
                    )
                    try backfillV8RequirementAssurance(
                        in: context,
                        workspaceID: workspaceID,
                        migrationID: id
                    )
                }
            }
            if recordsSchemaVersion < 8 {
                try autoreleasepool {
                    let container = try makeV9Container(at: modelURL, migrate: true)
                    try backfillV9Marker(in: container.mainContext, migrationID: id)
                }
            }
            let firstTargetPersistentSchemaVersion = max(recordsSchemaVersion + 2, 10)
            let currentPersistentSchemaVersion = PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
            if firstTargetPersistentSchemaVersion <= currentPersistentSchemaVersion {
                for targetPersistentSchemaVersion in
                    firstTargetPersistentSchemaVersion...currentPersistentSchemaVersion {
                    try autoreleasepool {
                        try advanceRestoreStagingGeneration(
                            at: modelURL,
                            toPersistentSchemaVersion: targetPersistentSchemaVersion,
                            migrationID: id
                        )
                    }
                }
            } else {
                _ = try autoreleasepool {
                    let container = try makeV53Container(at: modelURL, migrate: false)
                    return try requireV53Marker(
                        in: container.mainContext,
                        expectedMigrationID: id
                    )
                }
            }
            try authority.protectStagingGeneration(id: id)
            try authority.requireStagingGeneration(id: id)
            guard try itemType(
                at: root.appendingPathComponent(Self.modelStoreName)
            ) == .typeRegular else {
                throw StoreGenerationFailure.dataGenerationMissing
            }
        } catch {
            try? authority.removeStagingGeneration(id: id)
            throw error
        }
    }

    @MainActor
    private func makeFreshRestoreSourceContainer(
        at modelStoreURL: URL,
        recordsSchemaVersion: Int,
        markerMigrationID: UUID
    ) throws -> ModelContainer {
        let persistentSchemaVersion = recordsSchemaVersion + 1
        let container: ModelContainer
        switch persistentSchemaVersion {
        case 10: return try makeFreshV10Container(at: modelStoreURL, markerMigrationID: markerMigrationID)
        case 11: return try makeFreshV11Container(at: modelStoreURL, markerMigrationID: markerMigrationID)
        case 12: return try makeFreshV12Container(at: modelStoreURL, markerMigrationID: markerMigrationID)
        case 13: container = try makeV13Container(at: modelStoreURL, migrate: false)
        case 14: container = try makeV14Container(at: modelStoreURL, migrate: false)
        case 15: container = try makeV15Container(at: modelStoreURL, migrate: false)
        case 16: container = try makeV16Container(at: modelStoreURL, migrate: false)
        case 17: container = try makeV17Container(at: modelStoreURL, migrate: false)
        case 18: container = try makeV18Container(at: modelStoreURL, migrate: false)
        case 19: container = try makeV19Container(at: modelStoreURL, migrate: false)
        case 20: container = try makeV20Container(at: modelStoreURL, migrate: false)
        case 21: container = try makeV21Container(at: modelStoreURL, migrate: false)
        case 22: container = try makeV22Container(at: modelStoreURL, migrate: false)
        case 23: container = try makeV23Container(at: modelStoreURL, migrate: false)
        case 24: container = try makeV24Container(at: modelStoreURL, migrate: false)
        case 25: container = try makeV25Container(at: modelStoreURL, migrate: false)
        case 26: container = try makeV26Container(at: modelStoreURL, migrate: false)
        case 27: container = try makeV27Container(at: modelStoreURL, migrate: false)
        case 28: container = try makeV28Container(at: modelStoreURL, migrate: false)
        case 29: container = try makeV29Container(at: modelStoreURL, migrate: false)
        case 30: container = try makeV30Container(at: modelStoreURL, migrate: false)
        case 31: container = try makeV31Container(at: modelStoreURL, migrate: false)
        case 32: container = try makeV32Container(at: modelStoreURL, migrate: false)
        case 33: container = try makeV33Container(at: modelStoreURL, migrate: false)
        case 34: container = try makeV34Container(at: modelStoreURL, migrate: false)
        case 35: container = try makeV35Container(at: modelStoreURL, migrate: false)
        case 36: container = try makeV36Container(at: modelStoreURL, migrate: false)
        case 37: container = try makeV37Container(at: modelStoreURL, migrate: false)
        case 38: container = try makeV38Container(at: modelStoreURL, migrate: false)
        case 39: container = try makeV39Container(at: modelStoreURL, migrate: false)
        case 40: container = try makeV40Container(at: modelStoreURL, migrate: false)
        case 41: container = try makeV41Container(at: modelStoreURL, migrate: false)
        case 42: container = try makeV42Container(at: modelStoreURL, migrate: false)
        case 43: container = try makeV43Container(at: modelStoreURL, migrate: false)
        case 44: container = try makeV44Container(at: modelStoreURL, migrate: false)
        case 45: container = try makeV45Container(at: modelStoreURL, migrate: false)
        case 46: container = try makeV46Container(at: modelStoreURL, migrate: false)
        case 47: container = try makeV47Container(at: modelStoreURL, migrate: false)
        case 48: container = try makeV48Container(at: modelStoreURL, migrate: false)
        case 49: container = try makeV49Container(at: modelStoreURL, migrate: false)
        case 50: container = try makeV50Container(at: modelStoreURL, migrate: false)
        case 51: container = try makeV51Container(at: modelStoreURL, migrate: false)
        case 52: container = try makeV52Container(at: modelStoreURL, migrate: false)
        case 53: container = try makeV53Container(at: modelStoreURL, migrate: false)
        default: throw StoreGenerationFailure.dataPointerInvalid
        }
        guard let release = PersistentSchemaReleaseV1(rawValue: "V\(persistentSchemaVersion)"),
              let predecessor = PersistentSchemaReleaseV1(
                  rawValue: "V\(persistentSchemaVersion - 1)"
              ) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let context = container.mainContext
        context.insert(PersistentSchemaReleaseMarker(
            id: PersistentSchemaReleaseRegistryV1.v2MarkerID,
            schemaVersion: persistentSchemaVersion,
            releaseID: release.compatibilityID,
            predecessorReleaseID: predecessor.compatibilityID,
            migrationID: markerMigrationID
        ))
        try context.save()
        return container
    }

