    @MainActor
    private func quarantineAndRemovePruneCandidate(
        _ epoch: GenerationEpochV1,
        operationID: UUID,
        store: StoreMigrationJournalStoreV1
    ) throws {
        let parent = try openOwnedDirectory(at: generationsURL)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: generationsURL, descriptor: parent)
        let sourceName = canonicalString(for: epoch.generationID)
        let prefix = ".prune-\(canonicalString(for: operationID))-\(sourceName)-"
        let existing = try StoreRestoreGenerationAuthority.names(in: parent)
            .filter { $0.hasPrefix(prefix) }
        guard existing.count <= 1 else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }

        let quarantineName: String
        let expectedIdentity: StoreRestoreGenerationAuthority.Identity
        if try StoreRestoreGenerationAuthority.itemExists(
            parent: parent,
            name: sourceName
        ) {
            guard existing.isEmpty else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            let source = Darwin.openat(
                parent,
                sourceName,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
            guard source >= 0 else {
                throw diagnosedGenerationLeaseInvalidIdentityV1()
            }
            defer { _ = Darwin.close(source) }
            expectedIdentity = try StoreRestoreGenerationAuthority
                .directoryIdentity(descriptor: source)
            guard let provedEpoch = try acceptedGenerationEpoch(
                id: epoch.generationID,
                store: store,
                expectedRootIdentity: expectedIdentity
            ), provedEpoch == epoch,
                  try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(
                      parent: parent,
                      name: sourceName
                  ) == expectedIdentity else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            quarantineName = "\(prefix)\(expectedIdentity.device)-\(expectedIdentity.inode)"
            guard Darwin.renameatx_np(
                parent,
                sourceName,
                parent,
                quarantineName,
                UInt32(RENAME_EXCL)
            ) == 0,
                  Darwin.fsync(parent) == 0 else {
                throw diagnosedGenerationLeaseInvalidIdentityV1()
            }
            let renamedIdentity = try StoreRestoreGenerationAuthority
                .requiredDirectoryIdentity(parent: parent, name: quarantineName)
            guard renamedIdentity == expectedIdentity else {
                throw diagnosedGenerationLeaseInvalidIdentityV1()
            }
            try removeQuarantinedGeneration(
                parent: parent,
                name: quarantineName,
                expectedIdentity: expectedIdentity
            )
            return
        }

        guard let recoveredName = existing.first,
              let recoveredIdentity = pruneQuarantineIdentity(
                  name: recoveredName,
                  prefix: prefix
              ) else {
            // Neither source nor quarantine exists: a prior attempt completed
            // byte removal before it could advance the durable intent.
            return
        }
        quarantineName = recoveredName
        expectedIdentity = recoveredIdentity
        try removeQuarantinedGeneration(
            parent: parent,
            name: quarantineName,
            expectedIdentity: expectedIdentity
        )
    }

    private func removeQuarantinedGeneration(
        parent: Int32,
        name: String,
        expectedIdentity: StoreRestoreGenerationAuthority.Identity
    ) throws {
        guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(parent: parent, name: name) == expectedIdentity else {
            throw diagnosedGenerationLeaseInvalidIdentityV1()
        }
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw diagnosedGenerationLeaseInvalidIdentityV1() }
        defer { _ = Darwin.close(descriptor) }
        guard try StoreRestoreGenerationAuthority.directoryIdentity(descriptor: descriptor) == expectedIdentity else {
            throw diagnosedGenerationLeaseInvalidIdentityV1()
        }
        try StoreRestoreGenerationAuthority.removeContents(of: descriptor, authorityCheck: {
            try self.verifyOwnedDirectory(at: self.generationsURL, descriptor: parent)
            guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(parent: parent, name: name) == expectedIdentity else {
                throw diagnosedGenerationLeaseInvalidIdentityV1()
            }
        })
        guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(parent: parent, name: name) == expectedIdentity,
              Darwin.unlinkat(parent, name, AT_REMOVEDIR) == 0,
              Darwin.fsync(parent) == 0 else { throw diagnosedGenerationLeaseInvalidIdentityV1() }
    }

    private func pruneQuarantineIdentity(
        name: String,
        prefix: String
    ) -> StoreRestoreGenerationAuthority.Identity? {
        guard name.hasPrefix(prefix) else { return nil }
        let components = name.dropFirst(prefix.count).split(separator: "-")
        guard components.count == 2,
              let device = UInt64(components[0]),
              let inode = UInt64(components[1]) else {
            return nil
        }
        return StoreRestoreGenerationAuthority.Identity(
            device: dev_t(device),
            inode: ino_t(inode)
        )
    }

    private func pruneInventoryDigest(
        currentEpoch: GenerationEpochV1,
        retiredEpochs: [GenerationEpochV1],
        activeEpochs: Set<GenerationEpochV1>,
        uncertainGenerationIDs: [UUID]
    ) throws -> String {
        let inventory = StoreGenerationPruneInventoryV1(
            currentEpoch: currentEpoch,
            retiredEpochs: retiredEpochs.sorted(by: Self.epochOrder),
            activeEpochs: activeEpochs.sorted(by: Self.epochOrder),
            uncertainGenerationIDs: uncertainGenerationIDs.sorted(
                by: Self.idOrder
            )
        )
        return StoreMigrationCanonicalJSONV1.sha256(
            try StoreMigrationCanonicalJSONV1.encode(inventory)
        )
    }

    private static func epochOrder(
        _ lhs: GenerationEpochV1,
        _ rhs: GenerationEpochV1
    ) -> Bool {
        idOrder(lhs.generationID, rhs.generationID)
    }

    private static func idOrder(_ lhs: UUID, _ rhs: UUID) -> Bool {
        lhs.uuidString.lowercased() < rhs.uuidString.lowercased()
    }

    @MainActor
    func openInstalledGeneration(id: UUID) throws -> StoreGenerationSession {
        try openInstalledGeneration(
            id: id,
            authority: makeRestoreGenerationAuthority()
        )
    }

#if DEBUG
    /// A private-minted, one-use post-handoff witness is required. Ordinary
    /// generation opening would acquire SH against this fixture's retained EX.
    @MainActor
    func makeV949RetiredSourceFixtureOwner(
        witness: V949PostHandoffHostileFixtureWitnessV1
    ) throws -> V949RetiredSourceFixtureOwnerV1 {
        try V949RetiredSourceFixtureOwnerV1.acquire(
            factory: self, witness: witness)
    }

    @MainActor
    func captureV949RestoredSourceReaderExit(
        session: StoreGenerationSession
    ) throws -> V949RestoredSourceReaderExitV1 {
        try V949RestoredSourceReaderExitV1.capture(
            session: session, factory: self)
    }

    /// A deliberately hostile V9_49 row edit uses the original retired
    /// generation only after the original Erase owner checked closed. The
    /// caller already holds a new EX and retains this exact allocation before
    /// SwiftData construction; ordinary `openInstalledGeneration` would take
    /// a conflicting SH activity and cannot be substituted here.
    @MainActor
    func openV949RetiredSourceUnderExclusive(
        witness: V949PostHandoffHostileFixtureWitnessV1,
        allocation: GenerationLeaseAllocationAttemptV1,
        reader: GenerationLeaseHandleV1,
        contextObservation: EraseOriginalColdExitContextObservationV1
    ) throws -> StoreGenerationSession {
        try witness.requireFixtureOwnerStarted()
        let binding = witness.binding
        guard applicationSupportURL.standardizedFileURL
                == witness.subject.applicationSupportURL,
              allocation.generationEpoch.generationID == binding.oldGenerationID,
              allocation.generationEpoch.generationManifestSHA256
                == binding.sourceManifestSHA256,
              reader.token.epoch.generationID == binding.oldGenerationID,
              reader.token.role == .reader,
              allocation.allocatedHandle === reader else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let generationRootURL = installedGenerationURL(id: binding.oldGenerationID)
        guard generationRootURL.lastPathComponent
                == binding.oldGenerationID.uuidString.lowercased(),
              try itemType(at: generationRootURL) == .typeDirectory else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
        try protectGeneration(at: generationRootURL,
            staging: false, requireModel: true)
        let modelURL = generationRootURL.appendingPathComponent(
            Self.modelStoreName, isDirectory: false)
        guard try itemType(at: modelURL) == .typeRegular else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
        let container = try makeV53Container(at: modelURL, migrate: false)
        try contextObservation.complete(container)
        _ = try requireV53Marker(in: container.mainContext,
            expectedMigrationID: nil)
        try protectGeneration(at: generationRootURL,
            staging: false, requireModel: true)
        guard binding.sourcePointer.generationID
                == binding.oldGenerationID,
              binding.sourcePointer.generationManifestSHA256
                == binding.sourceManifestSHA256 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let identity = try WorkspaceReplicaIdentityV1(
            workspaceID: WorkspaceID(
                rawValue: binding.sourcePointer.workspaceID),
            replicaID: ReplicaID(
                rawValue: binding.sourcePointer.replicaID))
        return StoreGenerationSession(
            generationID: binding.oldGenerationID,
            generationRootURL: generationRootURL,
            workspaceIdentity: identity,
            modelContainer: container,
            storeSchemaRelease: PersistentSchemaReleaseRegistryV1.activeRelease,
            generationEpoch: allocation.generationEpoch,
            readerLeaseHandle: reader,
            afterSaveReproof: { [factory = self.forSaveReproof()] in
                try factory.protectGeneration(at: generationRootURL,
                    staging: false, requireModel: true)
            })
    }
#endif

    @MainActor
    func openInstalledGeneration(
        id: UUID,
        authority: StoreRestoreGenerationAuthority
    ) throws -> StoreGenerationSession {
        let currentBefore = try authority.currentGenerationID()
        let identity = try installedOpenIdentity(
            id: id,
            currentGenerationID: currentBefore
        )
        let session = try openGeneration(
            id: id,
            at: installedGenerationURL(id: id),
            identity: identity
        )
        try authority.protectInstalledGeneration(id: id)
        try authority.requireInstalledGeneration(id: id)
        guard try authority.currentGenerationID() == currentBefore else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return session
    }

    @MainActor
    func openInstalledGeneration(
        id: UUID,
        identity: WorkspaceReplicaIdentityV1,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> StoreGenerationSession {
        let session = try openGeneration(
            id: id,
            at: installedGenerationURL(id: id),
            identity: identity,
            diagnosticPhase: diagnosticPhase
        )
        diagnosticPhase?("installed-open.session.done")
        try authority.protectInstalledGeneration(id: id)
        diagnosticPhase?("installed-open.protection.done")
        try authority.requireInstalledGeneration(id: id)
        diagnosticPhase?("installed-open.authority.done")
        return session
    }

    @MainActor
    private func installedOpenIdentity(
        id: UUID,
        currentGenerationID: UUID
    ) throws -> WorkspaceReplicaIdentityV1 {
        guard id == currentGenerationID else {
            return pointerEnrichmentIdentity
        }
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        guard canonicalUUID(from: envelope.generationID) == id else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch envelope {
        case .legacy:
            return pointerEnrichmentIdentity
        case .v2(let pointer, _):
            return try compatibilityIdentity(for: pointer)
        case .v3(let pointer, _):
            _ = try requireCurrentManifest(pointer)
            return try pointer.identity()
        }
    }

    @MainActor
    func openRestoreStagingGeneration(id: UUID) throws -> StoreGenerationSession {
        try openGeneration(id: id, at: restoreStagingGenerationURL(id: id))
    }

    @MainActor
    func openRestoreStagingGeneration(
        id: UUID,
        authority: StoreRestoreGenerationAuthority
    ) throws -> StoreGenerationSession {
        try authority.requireStagingGeneration(id: id)
        try authority.protectStagingGeneration(id: id)
        let session = try openGeneration(id: id, at: restoreStagingGenerationURL(id: id))
        try authority.protectStagingGeneration(id: id)
        try authority.requireStagingGeneration(id: id)
        return session
    }

    @MainActor
    func openRestoreStagingGeneration(
        id: UUID,
        identity: WorkspaceReplicaIdentityV1,
        authority: StoreRestoreGenerationAuthority,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> StoreGenerationSession {
        try authority.requireStagingGeneration(id: id)
        try authority.protectStagingGeneration(id: id)
        let session = try openGeneration(
            id: id,
            at: restoreStagingGenerationURL(id: id),
            identity: identity,
            diagnosticPhase: diagnosticPhase
        )
        try authority.protectStagingGeneration(id: id)
        try authority.requireStagingGeneration(id: id)
        return session
    }

    static func backupImportStagingDirectory(
        containing generationRootURL: URL
    ) throws -> URL {
        let root = generationRootURL.standardizedFileURL
        let generations = root.deletingLastPathComponent()
        let dataRoot = generations.deletingLastPathComponent()
        guard root.isFileURL,
              generations.lastPathComponent == Self.generationsDirectoryName,
              dataRoot.lastPathComponent == Self.dataDirectoryName,
              let generationID = UUID(uuidString: root.lastPathComponent),
              generationID.uuidString.lowercased() == root.lastPathComponent else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return dataRoot.deletingLastPathComponent()
            .appendingPathComponent("FieldEvidenceRestore", isDirectory: true)
            .appendingPathComponent("staging", isDirectory: true)
    }

    private var dataRootURL: URL {
        applicationSupportURL.appendingPathComponent(
            Self.dataDirectoryName,
            isDirectory: true
        )
    }

    private var generationsURL: URL {
        dataRootURL.appendingPathComponent(
            Self.generationsDirectoryName,
            isDirectory: true
        )
    }

    private func openOwnedDirectory(at url: URL) throws -> Int32 {
        let root = applicationSupportURL.standardizedFileURL
        let target = url.standardizedFileURL
        let insideRoot = target.path == root.path ||
            (root.path == "/"
                ? target.path.hasPrefix("/")
                : target.path.hasPrefix(root.path + "/"))
        guard root.isFileURL, target.isFileURL, insideRoot else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        let relativePath = String(target.path.dropFirst(root.path.count))
            .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        let components = relativePath.isEmpty
            ? []
            : relativePath.split(separator: "/").map(String.init)
        guard components.allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        var descriptor = Darwin.open(
            root.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for component in components {
            let next = Darwin.openat(
                descriptor,
                component,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
            guard next >= 0 else {
                _ = Darwin.close(descriptor)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            _ = Darwin.close(descriptor)
            descriptor = next
        }
        return descriptor
    }

    private func verifyOwnedDirectory(
        at url: URL,
        descriptor: Int32
    ) throws {
        var expected = stat()
        guard Darwin.fstat(descriptor, &expected) == 0,
              (expected.st_mode & S_IFMT) == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let reopened = try openOwnedDirectory(at: url)
        defer { _ = Darwin.close(reopened) }
        var actual = stat()
        guard Darwin.fstat(reopened, &actual) == 0,
              (actual.st_mode & S_IFMT) == S_IFDIR,
              actual.st_dev == expected.st_dev,
              actual.st_ino == expected.st_ino else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func removeOwnedEntry(parent: Int32, name: String) throws {
        var info = stat()
        guard Darwin.fstatat(parent, name, &info, AT_SYMLINK_NOFOLLOW) == 0 else {
            if errno == ENOENT { return }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch info.st_mode & S_IFMT {
        case S_IFLNK:
            guard Darwin.unlinkat(parent, name, 0) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        case S_IFREG:
            guard info.st_nlink == 1,
                  Darwin.unlinkat(parent, name, 0) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        case S_IFDIR:
            let child = Darwin.openat(
                parent,
                name,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
            guard child >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            do {
                for childName in try StoreRestoreGenerationAuthority.names(in: child) {
                    try removeOwnedEntry(parent: child, name: childName)
                }
            } catch {
                _ = Darwin.close(child)
                throw error
            }
            _ = Darwin.close(child)
            guard Darwin.unlinkat(parent, name, AT_REMOVEDIR) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        default:
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard Darwin.fsync(parent) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func createOwnedDirectory(parent: Int32, name: String) throws -> Int32 {
        guard Darwin.mkdirat(parent, name, mode_t(0o700)) == 0,
              Darwin.fsync(parent) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return descriptor
    }

    private func protect(
        _ kind: OwnedFileKindV1,
        at url: URL,
        authorityCheck: @escaping () throws -> Void = {}
    ) throws {
        do {
            let root = applicationSupportURL.standardizedFileURL
            let target = url.standardizedFileURL
            let insideRoot = root.path == "/"
                ? target.path.hasPrefix("/")
                : target.path.hasPrefix(root.path + "/")
            guard insideRoot else {
                throw ProtectedFilePolicyError.invalidRelativePath
            }
            let relativePath = String(target.path.dropFirst(root.path.count))
                .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
            try ProtectedFilePolicyV1.applyAndVerify(
                kind,
                relativePath: relativePath,
                within: root,
                authorityCheck: authorityCheck
            )
        } catch let failure as StoreGenerationFailure {
            throw failure
        } catch let error as ProtectedFilePolicyError
            where error == .protectedDataUnavailable {
            throw error
        } catch {
#if DEBUG
            if coldOpenDiagnosticForTesting {
                let originalError = error as NSError
                let rootPath = applicationSupportURL.standardizedFileURL.path
                let targetPath = url.standardizedFileURL.path
                let ownedPrefix = rootPath == "/" ? "/" : rootPath + "/"
                let diagnosticPath: String = targetPath.hasPrefix(ownedPrefix)
                    ? String(targetPath.dropFirst(ownedPrefix.count))
                    : "<outside-owned-root>"
                coldOpenDiagnostic("protect-failed kind=" + kind.rawValue
                    + " path=" + diagnosticPath
                    + " type=" + String(reflecting: type(of: error))
                    + " domain=" + originalError.domain
                    + " code=" + String(originalError.code))
            }
#endif
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }



    private func protectPointer(at url: URL) throws {
        try protectPointerFile(.generationPointer, at: url)
    }

    private func protectPointer(
        at url: URL,
        parent: Int32,
        root: URL
    ) throws {
        try protectPointerFile(
            .generationPointer,
            at: url,
            parent: parent,
            root: root
        )
    }

    private func protectPointerFile(
        _ kind: OwnedFileKindV1,
        at url: URL
    ) throws {
        let root = url.deletingLastPathComponent().standardizedFileURL
        let parent = try openOwnedDirectory(at: root)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: root, descriptor: parent)
        let parentIdentity = try StoreRestoreGenerationAuthority.directoryIdentity(
            descriptor: parent
        )
        try protect(
            kind,
            at: url,
            authorityCheck: {
                guard try StoreRestoreGenerationAuthority.directoryIdentity(
                          descriptor: parent
                      ) == parentIdentity else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try self.verifyOwnedDirectory(at: root, descriptor: parent)
            }
        )
    }

    private func protectPointerFile(
        _ kind: OwnedFileKindV1,
        at url: URL,
        parent: Int32,
        root: URL
    ) throws {
        try verifyOwnedDirectory(at: root, descriptor: parent)
        let parentIdentity = try StoreRestoreGenerationAuthority.directoryIdentity(
            descriptor: parent
        )
        try protect(
            kind,
            at: url,
            authorityCheck: {
                guard try StoreRestoreGenerationAuthority.directoryIdentity(
                          descriptor: parent
                      ) == parentIdentity else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                try self.verifyOwnedDirectory(at: root, descriptor: parent)
            }
        )
    }

    private func protectGeneration(
        at root: URL,
        staging: Bool,
        requireModel: Bool
    ) throws {
        let descriptor = try openOwnedDirectory(at: root)
        defer { _ = Darwin.close(descriptor) }
        try verifyOwnedDirectory(at: root, descriptor: descriptor)
        // Installed generations defer reserved private preparation to startup
        // retirement; restore staging keeps its exact closed membership.
        let inventory: StoreRestoreGenerationAuthority.GenerationInventory
        do {
            inventory = try StoreRestoreGenerationAuthority.GenerationInventory(
                parent: descriptor, requireModel: requireModel, defersLivePrivatePreparation: !staging
            )
        } catch StoreMigrationFailure.invalidPath {
            // Closed-membership rejection has the same public generation failure
            // as the protection boundary below. Other errors retain their type.
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let generationIdentity = inventory.root.identity
        try protect(staging ? .restoreStaging : .durableDirectory, at: root, authorityCheck: {
            try inventory.revalidate()
            guard try StoreRestoreGenerationAuthority.directoryIdentity(at: root) == generationIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        })
        try inventory.protect(rootURL: root, staging: staging) { kind, url, check in
            try self.protect(kind, at: url, authorityCheck: check)
        }
        try verifyOwnedDirectory(at: root, descriptor: descriptor)
    }

    private func publishPointer<Value: Encodable>(
        name: String,
        value: Value,
        in root: URL
    ) throws {
        let registry = try makeGenerationLeaseRegistry()
        try registry.withNoMigrationReservation {
            try publishPointerLocked(name: name, value: value, in: root)
        }
    }

    private func publishPointerLocked<Value: Encodable>(
        name: String,
        value: Value,
        in root: URL
    ) throws {
        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        try StoreRestoreGenerationAuthority.requireSafeBasename(name)
        let parent = try openOwnedDirectory(at: root)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: root, descriptor: parent)
        let temporaryName = ".\(name).restore-next"
        guard try !StoreRestoreGenerationAuthority.itemExists(parent: parent, name: name),
              try !StoreRestoreGenerationAuthority.itemExists(
                  parent: parent,
                  name: temporaryName
              ) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let target = root.appendingPathComponent(name, isDirectory: false)
        let temporary = root.appendingPathComponent(temporaryName, isDirectory: false)
        let data = try canonicalData(for: value)
        var published = false
        var publishedIdentity: StoreRestoreGenerationAuthority.RegularFileIdentity?
        do {
            try StoreRestoreGenerationAuthority.createRegularFile(
                parent: parent,
                name: temporaryName,
                data: data
            )
            try protectPointerFile(
                .generationPointerTemporary,
                at: temporary,
                parent: parent,
                root: root
            )
            try verifyOwnedDirectory(at: root, descriptor: parent)
            let temporaryIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
                parent: parent,
                name: temporaryName
            )
            publishedIdentity = temporaryIdentity
            guard try !StoreRestoreGenerationAuthority.itemExists(parent: parent, name: name),
                  Darwin.renameatx_np(
                      parent,
                      temporaryName,
                      parent,
                      name,
                      UInt32(RENAME_EXCL)
            ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            published = true
            guard Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verifyOwnedDirectory(at: root, descriptor: parent)
            try protectPointer(at: target, parent: parent, root: root)
            let current = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: name
            )
            guard current.data == data,
                  current.identity == temporaryIdentity,
                  try !StoreRestoreGenerationAuthority.itemExists(
                      parent: parent,
                      name: temporaryName
                  ) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } catch {
            if published,
               let publishedIdentity,
               let current = try? StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                   parent: parent,
                   name: name
               ),
               current.data == data,
               current.identity == publishedIdentity {
                _ = Darwin.unlinkat(parent, name, 0)
                _ = Darwin.fsync(parent)
            } else if (try? StoreRestoreGenerationAuthority.itemExists(
                parent: parent,
                name: temporaryName
            )) == true {
                _ = Darwin.unlinkat(parent, temporaryName, 0)
                _ = Darwin.fsync(parent)
            }
            throw error
        }
    }

    private func replacePointer<Value: Encodable>(
        name: String,
        value: Value,
        expectedData requiredExpectedData: Data? = nil
    ) throws {
        let registry = try makeGenerationLeaseRegistry()
        try registry.withNoMigrationReservation {
            try replacePointerLocked(
                name: name,
                value: value,
                expectedData: requiredExpectedData
            )
        }
    }

    private func replacePointerLocked<Value: Encodable>(
        name: String,
        value: Value,
        expectedData requiredExpectedData: Data? = nil
    ) throws {
        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        try StoreRestoreGenerationAuthority.requireSafeBasename(name)
        let root = dataRootURL
        let parent = try openOwnedDirectory(at: root)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: root, descriptor: parent)
        let target = root.appendingPathComponent(name, isDirectory: false)
        try protectPointer(at: target, parent: parent, root: root)
        let expectedRead = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
            parent: parent,
            name: name
        )
        let expected = expectedRead.data
        let expectedIdentity = expectedRead.identity
        if let requiredExpectedData,
           expected != requiredExpectedData {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let replacement = try canonicalData(for: value)
        let temporaryName = ".\(name).restore-next"
        let temporary = root.appendingPathComponent(temporaryName, isDirectory: false)
        if try StoreRestoreGenerationAuthority.itemExists(
            parent: parent,
            name: temporaryName
        ) {
            guard try StoreRestoreGenerationAuthority.readRegularFile(
                parent: parent,
                name: temporaryName
            ) == replacement else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try removeOwnedEntry(parent: parent, name: temporaryName)
        }
        let currentBeforeSwap = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
            parent: parent,
            name: name
        )
        guard currentBeforeSwap.data == expected,
              currentBeforeSwap.identity == expectedIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var published = false
        var publishedIdentity: StoreRestoreGenerationAuthority.RegularFileIdentity?
        do {
            try StoreRestoreGenerationAuthority.createRegularFile(
                parent: parent,
                name: temporaryName,
                data: replacement
            )
            try protectPointerFile(
                .generationPointerTemporary,
                at: temporary,
                parent: parent,
                root: root
            )
            try verifyOwnedDirectory(at: root, descriptor: parent)
            let replacementIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
                parent: parent,
                name: temporaryName
            )
            let current = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: name
            )
            guard current.identity == expectedIdentity,
                  current.data == expected,
                  Darwin.renameatx_np(
                      parent,
                      temporaryName,
                      parent,
                      name,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            published = true
            publishedIdentity = replacementIdentity
            guard Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try verifyOwnedDirectory(at: root, descriptor: parent)
            try protectPointer(at: target, parent: parent, root: root)
            let currentAfterSwap = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: name
            )
            let oldTemporary = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: temporaryName
            )
            guard currentAfterSwap.data == replacement,
                  currentAfterSwap.identity == replacementIdentity,
                  oldTemporary.data == expected,
                  oldTemporary.identity == expectedIdentity,
                  Darwin.unlinkat(parent, temporaryName, 0) == 0,
                  Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } catch {
            if published,
               let publishedIdentity,
               let current = try? StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                   parent: parent,
                   name: name
               ),
               current.data == replacement,
               current.identity == publishedIdentity {
                do {
                    let oldTemporary = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                        parent: parent,
                        name: temporaryName
                    )
                    guard oldTemporary.data == expected,
                          oldTemporary.identity == expectedIdentity,
                          Darwin.renameatx_np(
                              parent,
                              name,
                              parent,
                              temporaryName,
                              UInt32(RENAME_SWAP)
                          ) == 0,
                          Darwin.fsync(parent) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    try verifyOwnedDirectory(at: root, descriptor: parent)
                    try protectPointer(at: target, parent: parent, root: root)
                    let restored = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                        parent: parent,
                        name: name
                    )
                    let replacementTemporary = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                        parent: parent,
                        name: temporaryName
                    )
                    guard restored.data == expected,
                          restored.identity == expectedIdentity,
                          replacementTemporary.data == replacement,
                          replacementTemporary.identity == publishedIdentity,
                          Darwin.unlinkat(parent, temporaryName, 0) == 0,
                          Darwin.fsync(parent) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } catch {
                    if ProtectedFilePolicyV1.isProtectedDataUnavailable(error) {
                        throw error
                    }
                }
            }
            if (try? StoreRestoreGenerationAuthority.itemExists(
                parent: parent,
                name: temporaryName
            )) == true {
                _ = Darwin.unlinkat(parent, temporaryName, 0)
                _ = Darwin.fsync(parent)
            }
            throw error
        }
    }

    private func restorePointer(
        parent: Int32,
        root: URL,
        name: String,
        data: Data,
        expectedCurrentIdentity: StoreRestoreGenerationAuthority.RegularFileIdentity? = nil
    ) throws {
        let rollbackName = ".\(name).restore-rollback"
        let replacedIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
            parent: parent,
            name: name
        )
        if let expectedCurrentIdentity {
            guard replacedIdentity == expectedCurrentIdentity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        if try StoreRestoreGenerationAuthority.itemExists(
            parent: parent,
            name: rollbackName
        ) {
            try removeOwnedEntry(parent: parent, name: rollbackName)
        }
        try StoreRestoreGenerationAuthority.createRegularFile(
            parent: parent,
            name: rollbackName,
            data: data
        )
        let rollbackURL = root.appendingPathComponent(rollbackName, isDirectory: false)
        try protectPointerFile(
            .generationPointerTemporary,
            at: rollbackURL,
            parent: parent,
            root: root
        )
        try verifyOwnedDirectory(at: root, descriptor: parent)
        let publishedIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
            parent: parent,
            name: rollbackName
        )
        var swapped = false
        do {
            guard try StoreRestoreGenerationAuthority.regularFileIdentity(
                      parent: parent,
                      name: name
                  ) == replacedIdentity,
                  Darwin.renameatx_np(
                      parent,
                      rollbackName,
                      parent,
                      name,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            swapped = true
            guard Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try protectPointer(
                at: root.appendingPathComponent(name, isDirectory: false),
                parent: parent,
                root: root
            )
            let restored = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: name
            )
            let replaced = try StoreRestoreGenerationAuthority.regularFileIdentity(
                parent: parent,
                name: rollbackName
            )
            guard restored.data == data,
                  restored.identity == publishedIdentity,
                  replaced == replacedIdentity,
                  Darwin.unlinkat(parent, rollbackName, 0) == 0,
                  Darwin.fsync(parent) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            swapped = false
        } catch {
            if swapped,
               let currentIdentity = try? StoreRestoreGenerationAuthority.regularFileIdentity(
                   parent: parent,
                   name: name
               ),
               currentIdentity == publishedIdentity,
               let rollbackIdentity = try? StoreRestoreGenerationAuthority.regularFileIdentity(
                   parent: parent,
                   name: rollbackName
               ),
               rollbackIdentity == replacedIdentity {
                do {
                    guard Darwin.renameatx_np(
                              parent,
                              name,
                              parent,
                              rollbackName,
                              UInt32(RENAME_SWAP)
                          ) == 0,
                          Darwin.fsync(parent) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                } catch {
                    if ProtectedFilePolicyV1.isProtectedDataUnavailable(error) {
                        throw error
                    }
                }
            }
            throw error
        }
    }

    /// Shipping startup never receives an intermediate-schema session. Source
    /// recovery is allowed only before the separately frozen checkpoint.
#if DEBUG
    @MainActor
    func seedIsolatedLegacyStartupUITestIfEmpty() throws {
        let root = applicationSupportURL.standardizedFileURL
        guard let id = UUID(uuidString: root.lastPathComponent),
              id.uuidString.lowercased() == root.lastPathComponent,
              root.deletingLastPathComponent().lastPathComponent == "V23MigrationUITests" else {
            throw StoreMigrationFailure.invalidPath
        }
        let parentURL = root.deletingLastPathComponent()
        if try itemType(at: parentURL) == nil { try fileManager.createDirectory(at: parentURL, withIntermediateDirectories: true) }
        let parent = Darwin.open(parentURL.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard parent >= 0 else { throw StoreMigrationFailure.invalidIdentity }
        defer { _ = Darwin.close(parent) }
        if Darwin.mkdirat(parent, root.lastPathComponent, mode_t(0o700)) != 0, errno != EEXIST {
            throw StoreMigrationFailure.invalidIdentity
        }
        let descriptor = Darwin.openat(parent, root.lastPathComponent, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreMigrationFailure.invalidIdentity }
        defer { _ = Darwin.close(descriptor) }
        // Repeated launch never resets an existing test store or retries a
        // partially written fixture as though it were an empty installation.
        guard try StoreRestoreGenerationAuthority.names(in: descriptor).isEmpty else { return }
        let generationID = UUID()
        let generationRoot = installedGenerationURL(id: generationID)
        try fileManager.createDirectory(at: generationRoot, withIntermediateDirectories: true)
        try autoreleasepool {
            let container = try makeV1RecoveryContainer(at: generationRoot.appendingPathComponent(Self.modelStoreName))
            container.mainContext.autosaveEnabled = false
            try container.mainContext.save()
        }
        try publishPointerLocked(name: Self.currentPointerName,
            value: CurrentPointerV1(generationID: generationID.uuidString.lowercased(), schemaVersion: 1), in: dataRootURL)
        try publishPointerLocked(name: Self.retiredPointerName,
            value: RetiredPointerV1(generationIDs: [], schemaVersion: 1), in: dataRootURL)
        try protectGeneration(at: generationRoot, staging: false, requireModel: true)
        try verifyOwnedDirectory(at: root, descriptor: descriptor)
        guard Darwin.fsync(descriptor) == 0, Darwin.fsync(parent) == 0 else { throw StoreMigrationFailure.invalidIdentity }
    }
#endif

#if DEBUG
    /// Creates only a new absent test root. The synchronous callback seeds
    /// persisted producer facts, never a historical validation capability.
    @MainActor
    func seedReleasedCheckpointTestFixture(
        release: PersistentSchemaReleaseV1,
        generationID: UUID,
        migrationID: UUID,
        identity: WorkspaceReplicaIdentityV1,
        populate: (ModelContext) throws -> Void
    ) throws -> URL {
        guard [.v1, .v4, .v5, .v7, .v8, .v9, .v10, .v14, .v53].contains(release) else { throw StoreMigrationFailure.invalidContract }
        let root = applicationSupportURL.standardizedFileURL
        guard root.isFileURL, try itemType(at: root) == nil else { throw StoreMigrationFailure.invalidPath }
        let parent = Darwin.open(root.deletingLastPathComponent().path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard parent >= 0 else { throw StoreMigrationFailure.invalidIdentity }
        defer { _ = Darwin.close(parent) }
        guard Darwin.mkdirat(parent, root.lastPathComponent, mode_t(0o700)) == 0 else { throw StoreMigrationFailure.invalidIdentity }
        let descriptor = Darwin.openat(parent, root.lastPathComponent, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreMigrationFailure.invalidIdentity }
        defer { _ = Darwin.close(descriptor) }
        try verifyOwnedDirectory(at: root, descriptor: descriptor)
        let generationRoot = installedGenerationURL(id: generationID)
        try fileManager.createDirectory(at: generationRoot, withIntermediateDirectories: true)
        let modelURL = generationRoot.appendingPathComponent(Self.modelStoreName)
        weak var retainedContainer: ModelContainer?
        weak var retainedContext: ModelContext?
        try autoreleasepool {
            let container: ModelContainer
            switch release {
            case .v1: container = try makeV1RecoveryContainer(at: modelURL)
            case .v4: container = try makeFreshV4Container(at: modelURL, markerMigrationID: migrationID)
            case .v5: container = try makeFreshV5Container(at: modelURL, markerMigrationID: migrationID)
            case .v7: container = try makeFreshV7Container(at: modelURL, markerMigrationID: migrationID)
            case .v8: container = try makeFreshV8Container(at: modelURL, markerMigrationID: migrationID)
            case .v9: container = try makeFreshV9Container(at: modelURL, markerMigrationID: migrationID)
            default:
                container = try makeFreshRestoreSourceContainer(at: modelURL,
                    recordsSchemaVersion: release.versionIdentifier.major - 1, markerMigrationID: migrationID)
            }
            let context = container.mainContext
            context.autosaveEnabled = false
            retainedContainer = container; retainedContext = context
            try populate(context)
            try context.save()
        }
        guard retainedContainer == nil, retainedContext == nil else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
        }
        let semantic = try semanticExport(at: modelURL, release: release, markerMigrationID: release == .v1 ? nil : migrationID)
        try protectGeneration(at: generationRoot, staging: false, requireModel: true)
        if release == .v1 {
            try publishPointerLocked(name: Self.currentPointerName,
                value: CurrentPointerV1(generationID: generationID.uuidString.lowercased(), schemaVersion: 1), in: dataRootURL)
        } else {
            let manifest = try StoreGenerationManifestV1(generationID: generationID,
                predecessorGenerationID: syntheticPredecessor(excluding: generationID), migrationID: migrationID,
                storeSchemaRelease: release, semanticSHA256: StoreMigrationCanonicalJSONV1.sha256(semantic),
                frozenIdentityDigest: try frozenIdentityDigest(for: generationRoot),
                files: try generationFileDigests(at: generationRoot, durable: true))
            let store = try StoreMigrationJournalStoreV1(applicationSupportURL: root)
            let digest = try store.writeManifest(manifest)
            try publishPointerLocked(name: Self.currentPointerName,
                value: CurrentGenerationPointerV3(generationID: generationID, generationManifestSHA256: digest,
                    workspaceID: identity.workspaceID, replicaID: identity.replicaID,
                    storeSchemaVersion: release.versionIdentifier.major), in: dataRootURL)
        }
        try publishPointerLocked(name: Self.retiredPointerName,
            value: RetiredPointerV1(generationIDs: [], schemaVersion: 1), in: dataRootURL)
        try verifyOwnedDirectory(at: root, descriptor: descriptor)
        guard Darwin.fsync(descriptor) == 0, Darwin.fsync(parent) == 0 else { throw StoreMigrationFailure.invalidIdentity }
        return modelURL
    }
#endif

    @MainActor
    func hasAggregateMigrationReservation() throws -> Bool {
        guard let control = try StoreAggregateMigrationControlV1(applicationSupportURL: applicationSupportURL),
              let observed = try control.load(), observed.reservationIsActive else { return false }
        let registry = try makeGenerationLeaseRegistry()
        return try registry.withExclusiveGenerationMutationLock {
            guard try control.load() == observed else { throw StoreMigrationFailure.maintenanceRequired(.invalidJournal) }
            try control.requireNoConflictingIntentAuthority()
            return true
        }
    }

    @MainActor
    func openForStartup(
        validateContinuation: @MainActor () async throws -> Void = {},
        recoverOriginalSource: @MainActor (StoreMigrationSourceRecoveryAuthorityV1) async throws -> Void
    ) async throws -> StoreStartupOpenResultV1 {
        try await validateContinuation()
        try PersistentSchemaReleaseRegistryV1.validate()
        for (id, proof) in Self.aggregateSourceDrains where proof.isDrained { Self.aggregateSourceDrains.removeValue(forKey: id) }
        if try itemType(at: dataRootURL) == nil { return .ready(try openOrBootstrapCurrent()) }
        let store = try StoreMigrationJournalStoreV1(applicationSupportURL: applicationSupportURL)
        let registry = try makeGenerationLeaseRegistry()
        let control = try store.aggregateControl()
        var aggregate = try registry.withExclusiveGenerationMutationLock {
            let observed = try control.load()
            if observed?.reservationIsActive == true { try control.requireNoConflictingIntentAuthority() }
            return observed
        }
        let processID = (migrationIdentitySource ?? .live).makeProcessID()
        if aggregate == nil, let original = try store.loadJournal() {
            // Resume exactly the original adjacent authority, but never its
            // historical automatic continuation into another public pointer.
            let pending: StoreMigrationAwaitingValidationV1? = try autoreleasepool {
                _ = try resumeMigration(original, dataRootURL: dataRootURL, store: store,
                                        processID: processID, continueAdjacentMigration: false)
                return try store.loadJournal().map {
                    StoreMigrationAwaitingValidationV1(upgradeID: $0.migrationID, targetGenerationID: $0.targetGenerationID)
                }
            }
            if let pending { return .awaitingIndependentValidation(pending) }
        }
        if let existing = aggregate, existing.phase == .complete {
            guard case .v3(let pointer, _) = try decodeCurrentPointer(at: dataRootURL.appendingPathComponent(Self.currentPointerName)),
                  pointer.storeSchemaVersion == PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major else {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            return .ready(try openOrBootstrapCurrent())
        }
        if aggregate == nil {
            let current = try decodeCurrentPointer(at: dataRootURL.appendingPathComponent(Self.currentPointerName))
            if case .v3(let pointer, _) = current,
               pointer.storeSchemaVersion == PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major {
                return .ready(try openOrBootstrapCurrent())
            }
            aggregate = try prepareAggregateMigration(current: current, store: store, control: control,
                                                      registry: registry, processID: processID)
            try reachMigrationBoundary(.afterPreparedJournalWrite)
        }
        guard var journal = aggregate else { throw StoreMigrationFailure.invalidContract }
        if journal.ownerID != registry.ownerID {
            let prior = journal
            journal.ownerID = registry.ownerID; journal.revision += 1
            try registry.withProvenAbandonedMigrationOwner(ownerID: prior.ownerID) {
                try control.write(journal, expected: prior)
            }
        }
        try registry.withMigrationReservation(expected: journal) { try control.reconcile() }
        guard !Self.runningAggregateRecoveries.contains(journal.upgradeID),
              Self.aggregateSourceDrains[journal.upgradeID] == nil else {
#if DEBUG
            print("StoreMigration.aggregate.sourceUnavailable guard=pending-source-owner phase=\(journal.phase) runningRecovery=\(Self.runningAggregateRecoveries.contains(journal.upgradeID)) drainProofPresent=\(Self.aggregateSourceDrains[journal.upgradeID] != nil) " + (Self.aggregateSourceDrains[journal.upgradeID]?.diagnosticFacts ?? ""))
#endif
            throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
        }
        Self.runningAggregateRecoveries.insert(journal.upgradeID)
        defer { Self.runningAggregateRecoveries.remove(journal.upgradeID) }
        if journal.phase == .recoveringSource {
            try await recoverAggregateOriginal(journal, registry: registry, control: control,
                                               validateContinuation: validateContinuation,
                                               recoverOriginalSource: recoverOriginalSource)
            await Task.yield()
            try await validateContinuation()
            guard let proof = Self.aggregateSourceDrains[journal.upgradeID], proof.isDrained else {
#if DEBUG
                print("StoreMigration.aggregate.sourceUnavailable guard=original-recovery-drain phase=\(journal.phase) drainProofPresent=\(Self.aggregateSourceDrains[journal.upgradeID] != nil) " + (Self.aggregateSourceDrains[journal.upgradeID]?.diagnosticFacts ?? ""))
#endif
                throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
            }
            Self.aggregateSourceDrains.removeValue(forKey: journal.upgradeID)
            let prior = journal
            let checkpoint = try registry.withMigrationReservation(expected: prior) {
                try control.withOriginalSource(prior) {
                    try captureAggregateSourceCheckpoint(prior)
                }
            }
            journal.sourceCheckpoint = checkpoint; journal.phase = .sourceFrozen; journal.revision += 1
            try registry.withMigrationReservation(expected: prior) { try control.write(journal, expected: prior) }
        }
        return try resumeAggregateMigration(journal, store: store, control: control, registry: registry, processID: processID)
    }

    @MainActor
    private func prepareAggregateMigration(current: CurrentPointerEnvelopeV1, store: StoreMigrationJournalStoreV1,
                                           control: StoreAggregateMigrationControlV1, registry: GenerationLeaseRegistryV1,
                                           processID: UUID) throws -> StoreAggregateMigrationJournalV1 {
        try registry.withNoMigrationReservation {
            let authority = try makeRestoreGenerationAuthority()
            try authority.requireNoRestoreJournal(); try authority.requireNoEraseAuthority()
            guard try authority.restoreGenerationNames().isEmpty, try store.loadJournal() == nil,
                  try decodeCurrentPointer(at: dataRootURL.appendingPathComponent(Self.currentPointerName)).data == current.data,
                  let sourceID = canonicalUUID(from: current.generationID),
                  try !authority.retiredGenerationIDs().contains(sourceID) else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
            _ = try registry.reconcileAbandonedOwners()
            guard try !registry.activeEpochs().contains(where: { $0.generationID == sourceID }) else {
#if DEBUG
                print("StoreMigration.aggregate.sourceUnavailable guard=active-source-epoch phase=preparing")
#endif
                throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
            }
            let release: PersistentSchemaReleaseV1
            let manifestDigest: String?
            let migrationID: UUID
            let identity: WorkspaceReplicaIdentityV1
            let replicas: Set<ReplicaID>
            let identities = migrationIdentitySource ?? .live
            switch current {
            case .legacy:
                release = .v1; manifestDigest = nil; migrationID = identities.makeMigrationID()
                identity = pointerEnrichmentIdentity; replicas = [identity.replicaID]
            case .v2(let pointer, _):
                let manifest = try requireCurrentManifest(pointer)
                release = .v2; manifestDigest = pointer.generationManifestSHA256; migrationID = manifest.migrationID
                identity = try compatibilityIdentity(for: pointer); replicas = [identity.replicaID]
            case .v3(let pointer, _):
                let manifest = try requireCurrentManifest(pointer)
                release = manifest.storeSchemaRelease; manifestDigest = pointer.generationManifestSHA256; migrationID = manifest.migrationID
                identity = try pointer.identity(); replicas = try pointer.knownReplicaIdentitySet()
            }
            let root = installedGenerationURL(id: sourceID)
            var info = stat()
            guard Darwin.lstat(root.path, &info) == 0, info.st_mode & S_IFMT == S_IFDIR else { throw StoreMigrationFailure.invalidIdentity }
            let journal = StoreAggregateMigrationJournalV1(
                upgradeID: UUID(), ownerID: registry.ownerID, sourceGenerationID: sourceID, sourceRelease: release,
                originalPointerData: current.data, sourceRootDevice: UInt64(info.st_dev), sourceRootInode: UInt64(info.st_ino),
                activationManifestSHA256: manifestDigest, migrationID: migrationID, targetGenerationID: identities.makeGenerationID(),
                targetRelease: PersistentSchemaReleaseRegistryV1.activeRelease,
                workspaceID: identity.workspaceID.rawValue, replicaID: identity.replicaID.rawValue,
                knownReplicaIDs: replicas.map(\.rawValue).sorted { $0.uuidString < $1.uuidString }, originatingProcessID: processID)
            try journal.validate()
            try control.withOriginalSource(journal) { try control.write(journal, expected: nil) }
            return journal
        }
    }

    @MainActor
    private func recoverAggregateOriginal(_ journal: StoreAggregateMigrationJournalV1,
                                          registry: GenerationLeaseRegistryV1, control: StoreAggregateMigrationControlV1,
                                          validateContinuation: @MainActor () async throws -> Void,
                                          recoverOriginalSource: @MainActor (StoreMigrationSourceRecoveryAuthorityV1) async throws -> Void) async throws {
        var container: ModelContainer? = try registry.withMigrationReservation(expected: journal) {
            try control.withOriginalSource(journal) {
                try openReleasedContainer(at: installedGenerationURL(id: journal.sourceGenerationID).appendingPathComponent(Self.modelStoreName),
                    release: journal.sourceRelease, markerMigrationID: journal.sourceRelease == .v1 ? nil : journal.migrationID,
                    writableLegacy: true)
            }
        }
        var mutationGuard: StoreMigrationSourceMutationGuardV1? = try StoreMigrationSourceMutationGuardV1(registry: registry, control: control, expected: journal)
        guard let opened = container, let guardValue = mutationGuard else { throw StoreMigrationFailure.invalidIdentity }
        let proof = StoreMigrationSourceDrainProofV1(container: opened, mutationGuard: guardValue, registry: registry)
        Self.aggregateSourceDrains[journal.upgradeID] = proof
        var authority: StoreMigrationSourceRecoveryAuthorityV1? = StoreMigrationSourceRecoveryAuthorityV1(
            journal: journal, generationRootURL: installedGenerationURL(id: journal.sourceGenerationID), container: opened, mutationGuard: guardValue)
        do {
            try await recoverOriginalSource(authority!)
            try await validateContinuation()
            try Task.checkCancellation()
            guard try !authority!.recoveryContext().hasChanges else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
            try authority?.revokeAndRelease()
        } catch {
            try? authority?.revokeAndRelease()
            authority = nil; container = nil; mutationGuard = nil
            throw error
        }
        authority = nil; container = nil; mutationGuard = nil
    }

    @MainActor
    private func predictHistoricalObservationAndTime(recordID: UUID, in context: ModelContext,
        release: PersistentSchemaReleaseV1) throws -> ObservationAndTimeMigrationResultV1 {
        let records = try context.fetch(FetchDescriptor<WorkflowRecord>(predicate: #Predicate { $0.id == recordID }))
        guard records.count == 1, let record = records.first else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        let prediction = try ObservationAndTimeMigrationV1.migrate(existingObservationBasisData: nil,
            existingTemporalContextData: nil, couldNotVerifyKey: record.couldNotVerifyKey,
            couldNotVerifyDisplaySnapshot: record.couldNotVerifyDisplaySnapshot,
            couldNotVerifyRegistryVersion: record.couldNotVerifyRegistryVersion, observedAtUTC: record.observedAtUTC,
            recordedAtUTC: record.completedAt ?? record.startedAt, timeZoneID: record.timeZoneID,
            utcOffsetMinutes: record.utcOffsetMinutes, localDate: record.localDate, localTime: record.localTime)
        guard !prediction.requiresForwardRepair, let basis = prediction.observationBasisData,
              let temporal = prediction.temporalContextData else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        if release.versionIdentifier.major >= 5 {
            let rows = try context.fetch(FetchDescriptor<ObservationAndTimeRow>(predicate: #Predicate { $0.recordID == recordID }))
            guard rows.count == 1, let row = rows.first, row.observationBasisV1Data == basis,
                  row.temporalContextV1Data == temporal else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
            try row.validate()
        }
        return prediction
    }

    @MainActor
    private func predictedV8AssuranceBackfill(record: WorkflowRecord,
        workspaceID: UUID) throws -> StoreMigrationLegacyAssurancePredictionV1 {
        let mutationID = record.finalizationMutationID ?? record.id
        let timestamp = record.completedAt ?? record.startedAt
        let row = try RequirementAssuranceRow.blockingUnknownBackfill(workflowRecordID: record.id,
            workspaceID: workspaceID, evaluatedRevision: 1, requirementID: "legacy_assurance_unknown",
            requirementVersion: 1, requirementTypeID: "legacy_assurance_unknown",
            policySHA256: StoreMigrationCanonicalJSONV1.sha256(Data("legacy-assurance-unknown-v1".utf8)),
            mutationID: mutationID, timestamp: timestamp)
        return StoreMigrationLegacyAssurancePredictionV1(snapshot: try row.snapshot(), mutationID: mutationID, timestamp: timestamp)
    }

    @MainActor
    private func predictHistoricalAssurance(recordID: UUID, in context: ModelContext,
        journal: StoreAggregateMigrationJournalV1) throws -> StoreMigrationLegacyAssurancePredictionV1 {
        let records = try context.fetch(FetchDescriptor<WorkflowRecord>(predicate: #Predicate { $0.id == recordID }))
        guard records.count == 1, let record = records.first else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        let prediction = try predictedV8AssuranceBackfill(record: record, workspaceID: journal.workspaceID)
        if journal.sourceRelease.versionIdentifier.major >= 8 {
            let rows = try context.fetch(FetchDescriptor<RequirementAssuranceRow>(predicate: #Predicate { $0.workflowRecordID == recordID }))
            guard rows.count == 1, let row = rows.first, try row.snapshot() == prediction.snapshot,
                  row.mutationID == prediction.mutationID, row.createdAt == prediction.timestamp,
                  row.updatedAt == prediction.timestamp else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        }
        return prediction
    }

    @MainActor
    private func predictHistoricalAssetSemantics(assetID: UUID, in context: ModelContext,
        journal: StoreAggregateMigrationJournalV1) throws -> AssetSemanticPersistentSnapshotV1 {
        let assets = try context.fetch(FetchDescriptor<Asset>(predicate: #Predicate { $0.id == assetID }))
        guard assets.count == 1, let asset = assets.first else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        // journal.migrationID is derived from the immutable original activation
        // manifest (or allocated for V1), never from an observed semantic row.
        let workspaceID = WorkspaceID(rawValue: journal.workspaceID)
        let prediction = try predictedV10AssetBackfill(asset: asset, workspaceID: workspaceID, migrationID: journal.migrationID)
        if journal.sourceRelease.versionIdentifier.major >= 10 {
            guard try AssetSemanticPersistentSnapshotV1.load(workspaceID: workspaceID, assetID: assetID,
                in: context) == prediction else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        }
        return prediction
    }

    @MainActor
    private func captureAggregateSourceCheckpoint(_ journal: StoreAggregateMigrationJournalV1) throws -> StoreMigrationSourceCheckpointV1 {
        try captureAggregateSourceEvidence(journal).checkpoint
    }

    @MainActor
    private func captureAggregateSourceEvidence(_ journal: StoreAggregateMigrationJournalV1) throws
        -> (checkpoint: StoreMigrationSourceCheckpointV1, validated: StoreMigrationValidatedTerminalImagesV1) {
        let root = installedGenerationURL(id: journal.sourceGenerationID)
        let registry = try makeGenerationLeaseRegistry()
        guard let control = try StoreAggregateMigrationControlV1(applicationSupportURL: applicationSupportURL) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let authority = try makeRestoreGenerationAuthority()
        let beforeSnapshot = try authority.snapshotInstalledGeneration(id: journal.sourceGenerationID)
        let beforeTree = try authority.installedTree(id: journal.sourceGenerationID)
        let evidence = try withPrivateSemanticRead(at: root, release: journal.sourceRelease,
            markerMigrationID: journal.sourceRelease == .v1 ? nil : journal.migrationID,
            operationID: journal.upgradeID, expectedFiles: beforeSnapshot.files) { container, reproveCopy in
            let proof = StoreMigrationSourceDrainProofV1(readOnlyContainer: container, registry: registry)
            Self.aggregateSourceDrains[journal.upgradeID] = proof
            let capability = StoreMigrationHistoricalCheckpointAuthorityV1(container: container,
                journal: journal, registry: registry, control: control,
                bindingProof: {
                    let configurations = Array(container.configurations)
                    guard configurations.count == 1,
                          configurations[0].url.standardizedFileURL == reproveCopy.modelURL.standardizedFileURL,
                          !container.mainContext.autosaveEnabled, !container.mainContext.hasChanges else {
                        throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                    }
                    try reproveCopy.verify()
                    try control.withOriginalSource(journal) {}
                },
                legacyV10BaselineProof: {
                    // Ordinary adjacent producers preserve sourceManifest's
                    // migrationID. A restore with differing genesis fails; no
                    // observed row identity substitutes for this lineage.
                    try self.requireV10LegacyMigrationState(in: container.mainContext, migrationID: journal.migrationID)
                }, observationPrediction: { recordID in
                    try self.predictHistoricalObservationAndTime(recordID: recordID, in: container.mainContext,
                        release: journal.sourceRelease)
                }, assurancePrediction: { recordID in
                    try self.predictHistoricalAssurance(recordID: recordID, in: container.mainContext, journal: journal)
                }, assetPrediction: { assetID in
                    try self.predictHistoricalAssetSemantics(assetID: assetID, in: container.mainContext, journal: journal)
                })
            defer { capability.revokeAndRelease() }
            let validated = try MutationJournalStoreV1.validateOriginalCheckpoint(capability)
            return (try aggregateSemanticDigest(in: container.mainContext,
                release: journal.sourceRelease), validated)
        }
        guard let readProof = Self.aggregateSourceDrains[journal.upgradeID], readProof.isDrained else {
#if DEBUG
            print("StoreMigration.aggregate.sourceUnavailable guard=historical-read-drain phase=\(journal.phase) drainProofPresent=\(Self.aggregateSourceDrains[journal.upgradeID] != nil) " + (Self.aggregateSourceDrains[journal.upgradeID]?.diagnosticFacts ?? ""))
#endif
            throw StoreMigrationFailure.maintenanceRequired(.sourceUnavailable)
        }
        Self.aggregateSourceDrains.removeValue(forKey: journal.upgradeID)
        let snapshot = try authority.snapshotInstalledGeneration(id: journal.sourceGenerationID)
        let tree = try authority.installedTree(id: journal.sourceGenerationID)
        guard snapshot.files == beforeSnapshot.files,
              snapshot.frozenIdentityDigest == beforeSnapshot.frozenIdentityDigest,
              tree == beforeTree else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        let checkpoint = StoreMigrationSourceCheckpointV1(files: snapshot.files, directories: tree.directories.sorted(),
            frozenIdentityDigest: snapshot.frozenIdentityDigest, semanticSHA256: evidence.0)
        try checkpoint.validate()
        guard try authority.snapshotInstalledGeneration(id: journal.sourceGenerationID).frozenIdentityDigest == snapshot.frozenIdentityDigest,
              try authority.installedTree(id: journal.sourceGenerationID) == tree else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        return (checkpoint, evidence.1)
    }

    @MainActor
    private func requireAggregateSourceCheckpoint(_ journal: StoreAggregateMigrationJournalV1,
                                                  authority: StoreRestoreGenerationAuthority) throws {
        guard let checkpoint = journal.sourceCheckpoint else { throw StoreMigrationFailure.invalidContract }
        let snapshot = try authority.snapshotInstalledGeneration(id: journal.sourceGenerationID)
        guard snapshot.files == checkpoint.files, snapshot.frozenIdentityDigest == checkpoint.frozenIdentityDigest,
              try authority.installedTree(id: journal.sourceGenerationID).directories.sorted() == checkpoint.directories else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
    }

    @MainActor
    private func requireAggregateCandidate(_ journal: StoreAggregateMigrationJournalV1,
                                           authority: StoreRestoreGenerationAuthority, staging: Bool) throws -> URL {
        let identity = try authority.aggregateRootIdentity(id: journal.targetGenerationID, staging: staging)
        guard identity.device == journal.candidateRootDevice, identity.inode == journal.candidateRootInode,
              let checkpoint = journal.sourceCheckpoint else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
        let root = staging ? restoreStagingGenerationURL(id: journal.targetGenerationID) : installedGenerationURL(id: journal.targetGenerationID)
        let tree = staging ? try authority.stagingTree(id: journal.targetGenerationID) : try authority.installedTree(id: journal.targetGenerationID)
        guard tree.directories.sorted() == checkpoint.directories else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
        let files = try generationFileDigests(at: root, durable: true)
        let databaseNames: Set<String> = ["model.sqlite", "model.sqlite-wal", "model.sqlite-shm"]
        guard files.filter({ !databaseNames.contains($0.relativePath) }) == checkpoint.files.filter({ !databaseNames.contains($0.relativePath) }) else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        try authority.verify()
        return root
    }

    @MainActor
    private func captureAggregatePriorMutationState(_ journal: StoreAggregateMigrationJournalV1,
                                                    at root: URL) throws -> StoreAggregateMutationNormalizationV1? {
        try autoreleasepool {
            let container = try openReleasedContainer(at: root.appendingPathComponent(Self.modelStoreName),
                release: journal.currentCandidateRelease, markerMigrationID: journal.currentCandidateRelease == .v1 ? nil : journal.migrationID)
            let context = container.mainContext
            context.autosaveEnabled = false
            guard try aggregateSemanticDigest(in: context, release: journal.currentCandidateRelease) == journal.currentCandidateSemanticSHA256 else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
            guard journal.currentCandidateRelease.versionIdentifier.major >= 4 else { return nil }
            let states = try context.fetch(FetchDescriptor<WorkspaceMutationStateRow>())
            guard states.count == 1, let state = states.first,
                  state.workspaceID == journal.workspaceID, state.activeReplicaID == journal.replicaID else {
                throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
            }
            return StoreAggregateMutationNormalizationV1(generationID: state.generationID,
                mutableSemanticSHA256: state.mutableSemanticSHA256)
        }
    }

    @MainActor
    private func requireAggregatePriorProjection(_ journal: StoreAggregateMigrationJournalV1,
                                                 at root: URL, targetRelease: PersistentSchemaReleaseV1,
                                                 finalProjectionProof: StoreMigrationFinalProjectionProofV1? = nil) throws {
        if targetRelease == journal.targetRelease {
            guard let finalProjectionProof else { throw StoreMigrationFailure.invalidPhaseTransition }
            try withFinalAggregateCandidate(journal, at: root, registry: makeGenerationLeaseRegistry(),
                projectionProof: finalProjectionProof) { candidate in
                try MutationJournalStoreV1.withAggregatePriorProjectionRestored(candidate) { context in
                    guard try aggregateSemanticDigest(in: context,
                        release: journal.currentCandidateRelease) == journal.currentCandidateSemanticSHA256 else {
                        throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                    }
                }
            }
            return
        }
        try autoreleasepool {
            let container = try openReleasedContainer(at: root.appendingPathComponent(Self.modelStoreName),
                release: targetRelease, markerMigrationID: journal.migrationID)
            let context = container.mainContext
            context.autosaveEnabled = false
            guard !context.hasChanges else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
            defer { context.rollback() }
            if let original = journal.authorizedPriorMutationState {
                let states = try context.fetch(FetchDescriptor<WorkspaceMutationStateRow>())
                guard states.count == 1, let state = states.first,
                      state.workspaceID == journal.workspaceID, state.activeReplicaID == journal.replicaID else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                let currentGeneration = state.generationID, currentCheckpoint = state.mutableSemanticSHA256
                if targetRelease == .v6 {
                    guard currentGeneration == journal.targetGenerationID,
                          currentCheckpoint == original.mutableSemanticSHA256 else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                } else if targetRelease == .v8 {
                    guard (currentGeneration == original.generationID && currentCheckpoint == original.mutableSemanticSHA256)
                        || (currentGeneration == journal.targetGenerationID && currentCheckpoint == nil) else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                } else if targetRelease != journal.targetRelease {
                    guard currentGeneration == original.generationID, currentCheckpoint == original.mutableSemanticSHA256 else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                } else {
                    guard [original.generationID, journal.targetGenerationID].contains(currentGeneration) else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                }
                state.generationID = original.generationID
                state.mutableSemanticSHA256 = original.mutableSemanticSHA256
                defer { state.generationID = currentGeneration; state.mutableSemanticSHA256 = currentCheckpoint }
                guard try aggregateSemanticDigest(in: context, release: journal.currentCandidateRelease) == journal.currentCandidateSemanticSHA256 else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
            } else {
                guard try aggregateSemanticDigest(in: context, release: journal.currentCandidateRelease) == journal.currentCandidateSemanticSHA256 else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
            }
        }
    }

    @MainActor
    private func resumeAggregateMigration(_ persisted: StoreAggregateMigrationJournalV1,
                                          store: StoreMigrationJournalStoreV1, control: StoreAggregateMigrationControlV1,
                                          registry: GenerationLeaseRegistryV1, processID: UUID) throws -> StoreStartupOpenResultV1 {
        var journal = persisted
        let authority = try makeRestoreGenerationAuthority()
        func persist(_ update: (inout StoreAggregateMigrationJournalV1) throws -> Void) throws {
            let previous = journal
            try update(&journal)
            journal.revision = previous.revision + 1
            try registry.withMigrationReservation(expected: previous) { try control.write(journal, expected: previous) }
        }
        func requireFinal(staging: Bool) throws {
            let root = try requireAggregateCandidate(journal, authority: authority, staging: staging)
            guard let digest = journal.targetManifestSHA256 else { throw StoreMigrationFailure.invalidContract }
            let manifest = try store.loadManifest(targetGenerationID: journal.targetGenerationID, expectedDigest: digest)
            guard manifest.schemaVersion == 2, manifest.semanticDigestAlgorithm == .framedLayersV1,
                  manifest.predecessorGenerationID == journal.sourceGenerationID, manifest.migrationID == journal.migrationID,
                  manifest.storeSchemaRelease == journal.targetRelease,
                  manifest.semanticSHA256 == journal.currentCandidateSemanticSHA256,
                  try generationFileDigests(at: root, durable: true) == manifest.files,
                  try frozenIdentityDigest(for: root) == manifest.frozenIdentityDigest else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
        }
        while true {
            try Task.checkCancellation()
            switch journal.phase {
            case .recoveringSource:
                throw StoreMigrationFailure.invalidPhaseTransition
            case .sourceFrozen:
                try registry.withMigrationReservation(expected: journal) {
                    try control.withOriginalSource(journal) { try requireAggregateSourceCheckpoint(journal, authority: authority) }
                    let presence = try authority.presence(id: journal.targetGenerationID)
                    guard !presence.installed else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
                    if journal.candidateRootInode == nil {
                        // A directory without the durable created-inode binding
                        // is uncertain; it is never guessed to be our partial copy.
                        guard !presence.staging else { throw StoreMigrationFailure.maintenanceRequired(.targetUnavailable) }
                        let allocation = try control.createAllocation(expected: journal)
#if DEBUG
                        try migrationFailureInjection?.reachAggregate(.afterAllocationCreation)
#endif
                        try control.verifyAllocation(allocation)
                        try persist { $0.allocationID = allocation.id; $0.candidateRootDevice = allocation.device; $0.candidateRootInode = allocation.inode }
                        try control.verifyAllocation(allocation)
#if DEBUG
                        try migrationFailureInjection?.reachAggregate(.afterAllocationBinding)
#endif
                    }
                    try authority.publishAggregateAllocation(reservation: journal, control: control) {
#if DEBUG
                        try migrationFailureInjection?.reachAggregate(.afterAllocationRenameBeforeSync)
#endif
                    }
#if DEBUG
                    try migrationFailureInjection?.reachAggregate(.afterAllocationPublication)
#endif
                }
                try registry.withMigrationReservation(expected: journal) {
                    try control.withOriginalSource(journal) {
                        try requireAggregateSourceCheckpoint(journal, authority: authority)
                        try authority.clearAggregateStagingGeneration(reservation: journal)
                        try reachMigrationBoundary(.beforeSourceClone)
                        let clone = try authority.cloneAggregateSource(reservation: journal)
                        guard clone.files == journal.sourceCheckpoint?.files,
                              clone.frozenIdentityDigest == journal.sourceCheckpoint?.frozenIdentityDigest else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
                        _ = try requireAggregateCandidate(journal, authority: authority, staging: true)
                    }
                    try persist { $0.phase = .cloned }
                }
                try reachMigrationBoundary(.afterSourceClone)
            case .cloned:
                try persist { $0.phase = .migrating }
            case .migrating:
                if journal.authorizedTargetRelease == nil {
                    if journal.currentCandidateRelease == journal.targetRelease {
                        try registry.withMigrationReservation(expected: journal) {
                            let root = try requireAggregateCandidate(journal, authority: authority, staging: true)
                            let manifest = try StoreGenerationManifestV1(schemaVersion: 2, generationID: journal.targetGenerationID,
                                predecessorGenerationID: journal.sourceGenerationID, migrationID: journal.migrationID,
                                storeSchemaRelease: journal.targetRelease, semanticSHA256: journal.currentCandidateSemanticSHA256,
                                semanticDigestAlgorithm: .framedLayersV1, frozenIdentityDigest: try frozenIdentityDigest(for: root), files: try generationFileDigests(at: root, durable: true))
                            let digest = try store.writeManifest(manifest)
                            let pointer = try CurrentGenerationPointerV3(generationID: journal.targetGenerationID,
                                generationManifestSHA256: digest, workspaceID: WorkspaceID(rawValue: journal.workspaceID),
                                replicaID: ReplicaID(rawValue: journal.replicaID),
                                knownReplicaIDs: Set(journal.knownReplicaIDs.map { ReplicaID(rawValue: $0) }),
                                storeSchemaVersion: journal.targetRelease.versionIdentifier.major)
                            let pointerData = try pointer.canonicalData()
                            try persist { $0.targetManifestSHA256 = digest; $0.desiredPointerData = pointerData; $0.phase = .targetValidated }
                        }
                        continue
                    }
                    guard let next = PersistentSchemaReleaseRegistryV1.releases.first(where: {
                        $0.predecessorVersionIdentifier == journal.currentCandidateRelease.versionIdentifier
                    }) else { throw StoreMigrationFailure.invalidPhaseTransition }
                    try registry.withMigrationReservation(expected: journal) {
                        let root = try requireAggregateCandidate(journal, authority: authority, staging: true)
                        let prior = try captureAggregatePriorMutationState(journal, at: root)
                        try persist { $0.authorizedTargetRelease = next; $0.authorizedPriorMutationState = prior }
                    }
                    try reachMigrationBoundary(.afterV2WriteAuthorization)
                }
                guard let next = journal.authorizedTargetRelease,
                      let input = journal.currentCandidateSemanticSHA256 else { throw StoreMigrationFailure.invalidContract }
                try registry.withMigrationReservation(expected: journal) {
                    try control.withOriginalSource(journal) {
                        try requireAggregateSourceCheckpoint(journal, authority: authority)
                        let root = try requireAggregateCandidate(journal, authority: authority, staging: true)
                        let finalProjectionProof = next == journal.targetRelease
                            ? try makeFinalAggregateProjectionProof(journal, at: root, registry: registry,
                                control: control, authority: authority) : nil
                        defer { finalProjectionProof?.revoke() }
                        try reachMigrationBoundary(.beforeV2Validation)
                        var output = try migrateAndValidateClone(at: root, sourceRelease: journal.currentCandidateRelease,
                            targetRelease: next, migrationID: journal.migrationID, sourceGenerationID: journal.sourceGenerationID,
                            targetGenerationID: journal.targetGenerationID, expectedSemanticDigest: input, aggregate: journal,
                            finalProjectionProof: finalProjectionProof)
#if DEBUG
                        try migrationFailureInjection?.reachAggregate(.afterAdjacentMarkerSave, targetRelease: next)
#endif
                        if next == journal.targetRelease {
                            guard let finalProjectionProof else { throw StoreMigrationFailure.invalidPhaseTransition }
                            output = try prepareFinalAggregateCandidate(journal, at: root, registry: registry,
                                projectionProof: finalProjectionProof)
#if DEBUG
                            try migrationFailureInjection?.reachAggregate(.afterFinalCheckpointSave, targetRelease: next)
#endif
                            try requireAggregatePriorProjection(journal, at: root, targetRelease: next,
                                finalProjectionProof: finalProjectionProof)
                        }
                        try protectGeneration(at: root, staging: true, requireModel: true)
                        _ = try requireAggregateCandidate(journal, authority: authority, staging: true)
                        let transition = StoreAggregateMigrationTransitionV1(sourceRelease: journal.currentCandidateRelease,
                            targetRelease: next, sourceSemanticSHA256: input, targetSemanticSHA256: output)
                        try persist { $0.transitions.append(transition); $0.authorizedTargetRelease = nil; $0.authorizedPriorMutationState = nil }
                    }
                }
                try reachMigrationBoundary(.afterV2Validation)
            case .targetValidated:
                try registry.withMigrationReservation(expected: journal) {
                    let presence = try authority.presence(id: journal.targetGenerationID)
                    guard presence.staging != presence.installed else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
                    try requireFinal(staging: presence.staging)
                    if presence.staging {
                        try reachMigrationBoundary(.beforeGenerationInstall)
                        try authority.installAggregateGeneration(reservation: journal)
                    }
                    try requireFinal(staging: false)
                    try persist { $0.phase = .generationInstalled }
                }
                try reachMigrationBoundary(.afterGenerationInstall)
            case .generationInstalled:
                try registry.withMigrationReservation(expected: journal) {
                    try requireFinal(staging: false)
                    if journal.publicationProcessID == nil { try persist { $0.publicationProcessID = processID } }
                    guard let bytes = journal.desiredPointerData else { throw StoreMigrationFailure.invalidContract }
                    let current = try decodeCurrentPointer(at: dataRootURL.appendingPathComponent(Self.currentPointerName))
                    if current.data != bytes {
                        guard current.data == journal.originalPointerData else { throw StoreMigrationFailure.maintenanceRequired(.invalidPointer) }
                        try requireAggregateSourceCheckpoint(journal, authority: authority)
                        try reachMigrationBoundary(.beforePointerPublication)
                        try replacePointerLocked(name: Self.currentPointerName,
                            value: CurrentGenerationPointerV3.decodeCanonical(from: bytes), expectedData: journal.originalPointerData)
                    }
                    try persist { $0.phase = .pointerPublished }
                }
                try reachMigrationBoundary(.afterPointerPublication)
            case .pointerPublished:
                try registry.withMigrationReservation(expected: journal) {
                    try requireFinal(staging: false)
                    try validateAggregatePublishedTarget(journal)
                    try persist { $0.firstValidationProcessID = processID; $0.phase = .awaitingIndependentValidation }
                }
                try reachMigrationBoundary(.afterFirstLaunchValidation)
                return .awaitingIndependentValidation(StoreMigrationAwaitingValidationV1(upgradeID: journal.upgradeID, targetGenerationID: journal.targetGenerationID))
            case .awaitingIndependentValidation:
                guard processID != journal.originatingProcessID, processID != journal.publicationProcessID,
                      processID != journal.firstValidationProcessID else {
                    return .awaitingIndependentValidation(StoreMigrationAwaitingValidationV1(upgradeID: journal.upgradeID, targetGenerationID: journal.targetGenerationID))
                }
                try registry.withMigrationReservation(expected: journal) {
                    try reachMigrationBoundary(.beforeSecondLaunchValidation)
                    try requireFinal(staging: false)
                    try validateAggregatePublishedTarget(journal)
                    try authority.retireGeneration(oldID: journal.sourceGenerationID, currentID: journal.targetGenerationID)
                    try persist { $0.secondValidationProcessID = processID; $0.phase = .complete }
                }
                try reachMigrationBoundary(.afterSecondLaunchValidation)
                return .ready(try openOrBootstrapCurrent())
            case .complete:
                return .ready(try openOrBootstrapCurrent())
            }
        }
    }

    @MainActor
    private func validateAggregatePublishedTarget(_ journal: StoreAggregateMigrationJournalV1) throws {
        guard try decodeCurrentPointer(at: dataRootURL.appendingPathComponent(Self.currentPointerName)).data == journal.desiredPointerData else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        guard let manifestDigest = journal.targetManifestSHA256 else { throw StoreMigrationFailure.invalidContract }
        let manifest = try StoreMigrationJournalStoreV1(applicationSupportURL: applicationSupportURL)
            .loadManifest(targetGenerationID: journal.targetGenerationID, expectedDigest: manifestDigest)
        guard manifest.schemaVersion == 2, manifest.semanticDigestAlgorithm == .framedLayersV1,
              manifest.storeSchemaRelease == journal.targetRelease,
              manifest.semanticSHA256 == journal.currentCandidateSemanticSHA256 else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let semantic: String = try withPrivateSemanticRead(
            at: installedGenerationURL(id: journal.targetGenerationID), release: journal.targetRelease,
            markerMigrationID: journal.migrationID, operationID: journal.upgradeID) { container, reprove in
            try reprove.verify()
            let value = try semanticDigest(in: container.mainContext, manifest: manifest)
            try reprove.verify()
            return value
        }
        guard semantic == journal.currentCandidateSemanticSHA256 else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
    }

    @MainActor
    private func makeFinalAggregateProjectionProof(_ journal: StoreAggregateMigrationJournalV1, at root: URL,
        registry: GenerationLeaseRegistryV1, control: StoreAggregateMigrationControlV1,
        authority: StoreRestoreGenerationAuthority) throws -> StoreMigrationFinalProjectionProofV1 {
        try requireAggregateSourceCheckpoint(journal, authority: authority)
        let evidence = try captureAggregateSourceEvidence(journal)
        guard evidence.checkpoint == journal.sourceCheckpoint,
              try requireAggregateCandidate(journal, authority: authority, staging: true).standardizedFileURL
                == root.standardizedFileURL else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        try requireAggregateSourceCheckpoint(journal, authority: authority)
        return try StoreMigrationFinalProjectionProofV1(validated: evidence.validated, journal: journal) {
            try registry.withMigrationReservation(expected: journal) {
                try control.withOriginalSource(journal) {
                    try self.requireAggregateSourceCheckpoint(journal, authority: authority)
                    guard try self.requireAggregateCandidate(journal, authority: authority, staging: true).standardizedFileURL
                        == root.standardizedFileURL else { throw StoreMigrationFailure.maintenanceRequired(.targetMismatch) }
                }
            }
        }
    }

    @MainActor
    private func prepareFinalAggregateCandidate(_ journal: StoreAggregateMigrationJournalV1, at root: URL,
        registry: GenerationLeaseRegistryV1, projectionProof: StoreMigrationFinalProjectionProofV1) throws -> String {
        try withFinalAggregateCandidate(journal, at: root, registry: registry, projectionProof: projectionProof) { candidate in
            try MutationJournalStoreV1.prepareAggregateCandidateForAdmission(candidate)
            return try candidate.withAuthorizedContext { context, _ in
                try aggregateSemanticDigest(in: context, release: journal.targetRelease)
            }
        }
    }

    @MainActor
    private func withFinalAggregateCandidate<Value>(_ journal: StoreAggregateMigrationJournalV1, at root: URL,
        registry: GenerationLeaseRegistryV1, projectionProof: StoreMigrationFinalProjectionProofV1,
        _ body: (StoreMigrationFinalCandidateAuthorityV1) throws -> Value) throws -> Value {
        try autoreleasepool {
            guard journal.targetRelease == .v53,
                  PersistentSchemaReleaseRegistryV1.activeRelease == .v53 else {
                throw StoreMigrationFailure.invalidPhaseTransition
            }
            let owned = try makeRestoreGenerationAuthority()
            let expectedRoot = try requireAggregateCandidate(journal, authority: owned, staging: true)
            guard root.standardizedFileURL == expectedRoot.standardizedFileURL else {
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            let modelURL = root.appendingPathComponent(Self.modelStoreName)
            let container = try makeV53Container(at: modelURL, migrate: false)
            _ = try requireV53Marker(in: container.mainContext, expectedMigrationID: journal.migrationID)
            container.mainContext.autosaveEnabled = false
            let candidate = StoreMigrationFinalCandidateAuthorityV1(container: container, registry: registry,
                journal: journal, projectionProof: projectionProof, reprove: {
                    let configurations = Array(container.configurations)
                    guard configurations.count == 1,
                          configurations[0].url.standardizedFileURL == modelURL.standardizedFileURL,
                          try self.requireAggregateCandidate(journal, authority: owned, staging: true).standardizedFileURL == root.standardizedFileURL else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                    _ = try self.requireV53Marker(in: container.mainContext, expectedMigrationID: journal.migrationID)
                })
            return try body(candidate)
        }
    }

    @MainActor
    func openOrBootstrapCurrent() throws -> StoreGenerationSession {
#if DEBUG
        coldOpenDiagnostic("schema-before")
#endif
        try PersistentSchemaReleaseRegistryV1.validate()
#if DEBUG
        coldOpenDiagnostic("schema-after")
#endif
        let dataRootURL = applicationSupportURL.appendingPathComponent(
            Self.dataDirectoryName,
            isDirectory: true
        )

        switch try itemType(at: dataRootURL) {
        case nil:
            try bootstrapDataRoot(at: dataRootURL)
        case .some(.typeDirectory):
            break
        case .some:
            throw StoreGenerationFailure.dataPointerInvalid
        }

#if DEBUG
        coldOpenDiagnostic("pointer-authority-before")
#endif
        let pointerAuthority = try makeRestoreGenerationAuthority()
        _ = try pointerAuthority.currentGenerationID()
        _ = try pointerAuthority.retiredGenerationIDs()
#if DEBUG
        coldOpenDiagnostic("pointer-authority-after")
        coldOpenDiagnostic("lease-registry-before")
#endif
        let leaseRegistry = try makeGenerationLeaseRegistry()
#if DEBUG
        coldOpenDiagnostic("lease-registry-after")
        coldOpenDiagnostic("prune-intent-before")
#endif
        if try leaseRegistry.loadPruneIntent() != nil {
#if DEBUG
            coldOpenDiagnostic("prune-intent-after-present")
            coldOpenDiagnostic("prune-reconcile-before")
#endif
            _ = try reconcileGenerationLeasesAndPrune()
#if DEBUG
            coldOpenDiagnostic("prune-reconcile-after")
#endif
        }
#if DEBUG
        coldOpenDiagnostic("prune-intent-check-after")
#endif

        do {
#if DEBUG
            coldOpenDiagnostic("migration-journal-store-before")
#endif
            let migrationStore = try StoreMigrationJournalStoreV1(
                applicationSupportURL: applicationSupportURL
            )
#if DEBUG
            coldOpenDiagnostic("migration-journal-store-after")
#endif
            let processID = (migrationIdentitySource ?? .live).makeProcessID()
#if DEBUG
            coldOpenDiagnostic("migration-journal-load-before")
#endif
            if let journal = try migrationStore.loadJournal() {
#if DEBUG
                coldOpenDiagnostic("migration-journal-load-after-present")
#endif
                return try resumeMigration(
                    journal,
                    dataRootURL: dataRootURL,
                    store: migrationStore,
                    processID: processID
                )
            }
#if DEBUG
            coldOpenDiagnostic("migration-journal-load-after-absent")
            coldOpenDiagnostic("open-current-before")
            let session = try openCurrent(
                in: dataRootURL,
                store: migrationStore,
                processID: processID
            )
            coldOpenDiagnostic("open-current-after")
            return session
#else
            return try openCurrent(
                in: dataRootURL,
                store: migrationStore,
                processID: processID
            )
#endif
        } catch let failure as StoreMigrationFailure {
            throw failure
        } catch {
            if let reason = migrationMaintenanceReason(for: error) {
                throw StoreMigrationFailure.maintenanceRequired(reason)
            }
            throw error
        }
    }

    @MainActor
    private func bootstrapDataRoot(at dataRootURL: URL) throws {
        // A missing data root is not proof of a new installation. Inspect
        // existing recovery owners before creating or cleaning any app bytes.
#if DEBUG
        coldOpenDiagnostic("bootstrap.recovery-authority-initial")
#endif
        try requireNoBootstrapRecoveryAuthority()
#if DEBUG
        coldOpenDiagnostic("bootstrap.support-directory")
#endif
        if try itemType(at: applicationSupportURL) == nil {
            try fileManager.createDirectory(at: applicationSupportURL, withIntermediateDirectories: true)
        }
#if DEBUG
        coldOpenDiagnostic("bootstrap.lease-registry")
#endif
        let registry = try makeGenerationLeaseRegistry()
#if DEBUG
        coldOpenDiagnostic("bootstrap.migration-reservation")
#endif
        try registry.withNoMigrationReservation {
#if DEBUG
            coldOpenDiagnostic("bootstrap.recovery-authority-reserved")
#endif
            try requireNoBootstrapRecoveryAuthority()
            try bootstrapDataRootWithoutRecoveryAuthority(at: dataRootURL)
        }
    }

    private func requireNoBootstrapRecoveryAuthority() throws {
        guard let rootType = try itemType(at: applicationSupportURL) else { return }
        guard rootType == .typeDirectory else { throw StoreGenerationFailure.dataPointerInvalid }
        func requireEmpty(_ relative: String, allowedEmptyDirectories: Set<String> = []) throws {
            let url = applicationSupportURL.appendingPathComponent(relative, isDirectory: true)
            guard let type = try itemType(at: url) else { return }
            guard type == .typeDirectory else { throw StoreGenerationFailure.dataPointerInvalid }
            let descriptor = try openOwnedDirectory(at: url)
            defer { _ = Darwin.close(descriptor) }
            let names = try StoreRestoreGenerationAuthority.names(in: descriptor)
            guard Set(names).isSubset(of: allowedEmptyDirectories) else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidJournal)
            }
            for name in names { try requireEmpty(relative + "/" + name) }
            try verifyOwnedDirectory(at: url, descriptor: descriptor)
        }
        try requireEmpty("FieldEvidenceOperations/schema-migration")
        try requireEmpty("FieldEvidenceErase")
        try requireEmpty("FieldEvidenceRestore", allowedEmptyDirectories: ["generations", "staging"])
    }

    @MainActor
    private func bootstrapDataRootWithoutRecoveryAuthority(at dataRootURL: URL) throws {
#if DEBUG
        coldOpenDiagnostic("bootstrap.directory-preflight")
#endif
        if let type = try itemType(at: applicationSupportURL),
           type != .typeDirectory {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try fileManager.createDirectory(
            at: applicationSupportURL,
            withIntermediateDirectories: true
        )
        guard try itemType(at: applicationSupportURL) == .typeDirectory else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        let bootstrapURL = applicationSupportURL.appendingPathComponent(
            Self.bootstrapDirectoryName,
            isDirectory: true
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.support-authority")
#endif
        let applicationSupportDescriptor = try openOwnedDirectory(at: applicationSupportURL)
        defer { _ = Darwin.close(applicationSupportDescriptor) }
        try verifyOwnedDirectory(
            at: applicationSupportURL,
            descriptor: applicationSupportDescriptor
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.stale-staging")
#endif
        if try StoreRestoreGenerationAuthority.itemExists(
            parent: applicationSupportDescriptor,
            name: Self.bootstrapDirectoryName
        ) {
            try removeOwnedEntry(
                parent: applicationSupportDescriptor,
                name: Self.bootstrapDirectoryName
            )
        }

#if DEBUG
        coldOpenDiagnostic("bootstrap.generation-directories")
#endif
        let generationID = migrationIdentitySource?.makeGenerationID() ?? UUID()
        let generationName = canonicalString(for: generationID)
        let bootstrapDescriptor = try createOwnedDirectory(
            parent: applicationSupportDescriptor,
            name: Self.bootstrapDirectoryName
        )
        defer { _ = Darwin.close(bootstrapDescriptor) }
        let bootstrapGenerationsDescriptor = try createOwnedDirectory(
            parent: bootstrapDescriptor,
            name: Self.generationsDirectoryName
        )
        defer { _ = Darwin.close(bootstrapGenerationsDescriptor) }
        let generationDescriptor = try createOwnedDirectory(
            parent: bootstrapGenerationsDescriptor,
            name: generationName
        )
        defer { _ = Darwin.close(generationDescriptor) }
        let generationRootURL = bootstrapURL
            .appendingPathComponent(Self.generationsDirectoryName, isDirectory: true)
            .appendingPathComponent(generationName, isDirectory: true)

        let bootstrapGenerationsURL = bootstrapURL.appendingPathComponent(
            Self.generationsDirectoryName,
            isDirectory: true
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.staging-protection")
#endif
        try protect(.stagingDirectory, at: bootstrapURL)
        try protect(.stagingDirectory, at: bootstrapGenerationsURL)
        try protect(.restoreStaging, at: generationRootURL)

        let modelStoreURL = generationRootURL.appendingPathComponent(
            Self.modelStoreName,
            isDirectory: false
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.empty-container")
#endif
        try createAndReleaseEmptyContainer(
            at: modelStoreURL,
            markerMigrationID: Self.bootstrapManifestMigrationID
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.journal-initialize")
#endif
        try autoreleasepool {
            let container = try makeV53Container(at: modelStoreURL, migrate: false)
            _ = try MutationJournalStoreV1(
                modelContext: container.mainContext,
                identity: pointerEnrichmentIdentity,
                generationID: generationID
            )
        }

#if DEBUG
        coldOpenDiagnostic("bootstrap.model-presence")
#endif
        guard try itemType(at: modelStoreURL) == .typeRegular else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
#if DEBUG
        coldOpenDiagnostic("bootstrap.generation-protection")
#endif
        try protectGeneration(at: generationRootURL, staging: false, requireModel: true)

        let bootstrapPredecessorID: UUID = syntheticPredecessor(excluding: generationID)
#if DEBUG
        coldOpenDiagnostic("bootstrap.semantic-digest")
#endif
        let bootstrapSemanticSHA256: String = try framedSemanticDigest(
            at: modelStoreURL,
            release: PersistentSchemaReleaseRegistryV1.activeRelease
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.frozen-identity")
#endif
        let bootstrapFrozenIdentityDigest: String = try frozenIdentityDigest(
            for: generationRootURL
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.physical-files")
#endif
        let bootstrapFiles: [StoreGenerationFileDigestV1] = try generationFileDigests(
            at: generationRootURL,
            durable: true
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.manifest-value")
#endif
        let manifest = try StoreGenerationManifestV1(
            schemaVersion: 2,
            generationID: generationID,
            predecessorGenerationID: bootstrapPredecessorID,
            migrationID: Self.bootstrapManifestMigrationID,
            storeSchemaRelease: PersistentSchemaReleaseRegistryV1.activeRelease,
            semanticSHA256: bootstrapSemanticSHA256,
            semanticDigestAlgorithm: .framedLayersV1,
            frozenIdentityDigest: bootstrapFrozenIdentityDigest,
            files: bootstrapFiles
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.manifest-store")
#endif
        let migrationStore = try StoreMigrationJournalStoreV1(
            applicationSupportURL: applicationSupportURL
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.manifest-write")
#endif
        let manifestDigest = try migrationStore.writeManifest(manifest)
#if DEBUG
        coldOpenDiagnostic("bootstrap.pointer-values")
#endif
        let currentPointer = try CurrentGenerationPointerV3(
            generationID: generationID,
            generationManifestSHA256: manifestDigest,
            workspaceID: pointerEnrichmentIdentity.workspaceID,
            replicaID: pointerEnrichmentIdentity.replicaID,
            storeSchemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major
        )
        let retiredPointer = RetiredPointerV1(
            generationIDs: [],
            schemaVersion: StorePointerSchemaRegistry.retiredVersion
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.current-pointer-publication")
#endif
        try publishPointer(
            name: Self.currentPointerName,
            value: currentPointer,
            in: bootstrapURL
        )
#if DEBUG
        coldOpenDiagnostic("bootstrap.retired-pointer-publication")
#endif
        try publishPointer(
            name: Self.retiredPointerName,
            value: retiredPointer,
            in: bootstrapURL
        )

#if DEBUG
        coldOpenDiagnostic("bootstrap.prepublication-protection")
#endif
        try protect(.durableDirectory, at: bootstrapURL)
        try protect(.durableDirectory, at: bootstrapGenerationsURL)
        try protectGeneration(at: generationRootURL, staging: false, requireModel: true)
        try protectPointer(
            at: bootstrapURL.appendingPathComponent(Self.currentPointerName, isDirectory: false)
        )
        try protectPointer(
            at: bootstrapURL.appendingPathComponent(Self.retiredPointerName, isDirectory: false)
        )

#if DEBUG
        coldOpenDiagnostic("bootstrap.root-publication")
#endif
        // The staging root is a fixed sibling, so this move is a same-volume
        // atomic publication of an already complete generation and pointers.
        try verifyOwnedDirectory(
            at: applicationSupportURL,
            descriptor: applicationSupportDescriptor
        )
        guard try !StoreRestoreGenerationAuthority.itemExists(
            parent: applicationSupportDescriptor,
            name: Self.dataDirectoryName
        ),
              Darwin.renameatx_np(
                  applicationSupportDescriptor,
                  Self.bootstrapDirectoryName,
                  applicationSupportDescriptor,
                  Self.dataDirectoryName,
                  UInt32(RENAME_EXCL)
              ) == 0,
              Darwin.fsync(applicationSupportDescriptor) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        coldOpenDiagnostic("bootstrap.published-root-protection")
#endif
        try protect(.durableDirectory, at: dataRootURL)
        let publishedGenerationsURL = dataRootURL.appendingPathComponent(
            Self.generationsDirectoryName,
            isDirectory: true
        )
        try protect(.durableDirectory, at: publishedGenerationsURL)
        try protectGeneration(
            at: publishedGenerationsURL.appendingPathComponent(
                generationName,
                isDirectory: true
            ),
            staging: false,
            requireModel: true
        )
        try protectPointer(
            at: dataRootURL.appendingPathComponent(
                Self.currentPointerName,
                isDirectory: false
            )
        )
        try protectPointer(
            at: dataRootURL.appendingPathComponent(
                Self.retiredPointerName,
                isDirectory: false
            )
        )
    }

    @MainActor
    private func openCurrent(
        in dataRootURL: URL,
        store: StoreMigrationJournalStoreV1,
        processID: UUID
    ) throws -> StoreGenerationSession {
        try protect(.durableDirectory, at: dataRootURL)
        let generationsRoot = dataRootURL.appendingPathComponent(
            Self.generationsDirectoryName,
            isDirectory: true
        )
        try protect(.durableDirectory, at: generationsRoot)
        let currentURL = dataRootURL.appendingPathComponent(
            Self.currentPointerName,
            isDirectory: false
        )
        let retiredURL = dataRootURL.appendingPathComponent(
            Self.retiredPointerName,
            isDirectory: false
        )
        guard try itemType(at: currentURL) == .typeRegular,
              try itemType(at: retiredURL) == .typeRegular else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try protectPointer(at: currentURL)
        try protectPointer(at: retiredURL)

#if DEBUG
        coldOpenDiagnostic("current-pointer-decode-before")
#endif
        let current = try decodeCurrentPointer(at: currentURL)
#if DEBUG
        coldOpenDiagnostic("current-pointer-decode-after")
        coldOpenDiagnostic("retired-pointer-decode-before")
#endif
        let retired: RetiredPointerV1 = try decodeCanonicalPointer(at: retiredURL)
#if DEBUG
        coldOpenDiagnostic("retired-pointer-decode-after")
#endif
        try StorePointerSchemaRegistry.requireRetired(retired.schemaVersion)
        let currentName: String
        let currentID: UUID
        switch current {
        case .legacy(let pointer, _):
            currentName = pointer.generationID
            guard let identifier = canonicalUUID(from: currentName) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            currentID = identifier
        case .v2(let pointer, _):
            currentName = pointer.generationID
            guard let identifier = canonicalUUID(from: currentName) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            currentID = identifier
        case .v3(let pointer, _):
            currentName = pointer.generationID
            guard let identifier = canonicalUUID(from: currentName) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            currentID = identifier
        }
        guard retired.generationIDs.allSatisfy({ canonicalUUID(from: $0) != nil }),
              retired.generationIDs == retired.generationIDs.sorted(),
              Set(retired.generationIDs).count == retired.generationIDs.count,
              !retired.generationIDs.contains(currentName) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        let generationsURL = generationsRoot
        guard let generationsType = try itemType(at: generationsURL) else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
        guard generationsType == .typeDirectory else {
            throw StoreGenerationFailure.dataPointerInvalid
        }

        let expectedGenerationNames = Set(
            [currentName] + retired.generationIDs
        )
        let actualGenerationNames: Set<String>
        do {
            actualGenerationNames = Set(
                try fileManager.contentsOfDirectory(atPath: generationsURL.path)
            )
        } catch {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard actualGenerationNames == expectedGenerationNames else {
            if expectedGenerationNames.subtracting(actualGenerationNames).isEmpty {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            throw StoreGenerationFailure.dataGenerationMissing
        }

        switch current {
        case .legacy(let pointer, let data):
            return try beginMigration(
                sourcePointer: pointer,
                sourcePointerData: data,
                retired: retired,
                dataRootURL: dataRootURL,
                store: store,
                processID: processID
            )
        case .v2(let pointer, _):
            let enriched = try enrichCurrentPointer(pointer)
            let sourceLease = try acquireCurrentReaderLease(
                epoch: GenerationEpochV1(
                    generationID: currentID,
                    generationManifestSHA256:
                        enriched.generationManifestSHA256
                ),
                expectedPointerData: try enriched.canonicalData()
            )
            return try withExtendedLifetime(sourceLease) {
                try beginMigration(
                    sourcePointer: enriched,
                    sourcePointerData: try enriched.canonicalData(),
                    retired: retired,
                    dataRootURL: dataRootURL,
                    store: store,
                    processID: processID
                )
            }
        case .v3(let pointer, let data):
            if pointer.storeSchemaVersion < PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major {
                let sourceLease = try acquireCurrentReaderLease(
                    epoch: GenerationEpochV1(
                        generationID: currentID,
                        generationManifestSHA256:
                            pointer.generationManifestSHA256
                    ),
                    expectedPointerData: data
                )
                return try withExtendedLifetime(sourceLease) {
                    try beginMigration(
                        sourcePointer: pointer,
                        sourcePointerData: data,
                        retired: retired,
                        dataRootURL: dataRootURL,
                        store: store,
                        processID: processID
                    )
                }
            }
#if DEBUG
            coldOpenDiagnostic("validated-current-before")
            let session = try openValidatedV3Current(
                pointer: pointer,
                dataRootURL: dataRootURL,
                store: store
            )
            coldOpenDiagnostic("validated-current-after")
            return session
#else
            return try openValidatedV3Current(pointer: pointer, dataRootURL: dataRootURL, store: store)
#endif
        }
    }

    @MainActor
    private func createAndReleaseEmptyContainer(
        at modelStoreURL: URL,
        markerMigrationID: UUID
    ) throws {
        try autoreleasepool {
            let container = try makeV53Container(
                at: modelStoreURL,
                migrate: false
            )
            do {
                let context = container.mainContext
                context.insert(PersistentSchemaReleaseMarker(
                    id: PersistentSchemaReleaseRegistryV1.v2MarkerID,
                    schemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major,
                    releaseID: PersistentSchemaReleaseRegistryV1.activeCompatibilityID,
                    predecessorReleaseID: PersistentSchemaReleaseV1.v52.compatibilityID,
                    migrationID: markerMigrationID
                ))
                try context.save()
                _ = try requireV53Marker(in: context, expectedMigrationID: markerMigrationID)
            }
        }
    }

    @MainActor
    private func openGeneration(
        id: UUID,
        at generationRootURL: URL,
        identity: WorkspaceReplicaIdentityV1? = nil,
        diagnosticPhase: (@MainActor (String) -> Void)? = nil
    ) throws -> StoreGenerationSession {
        diagnosticPhase?("generation-open.begin")
        try eraseReaderRetirementInventory?.requireUnsealed()
        guard generationRootURL.lastPathComponent == canonicalString(for: id) else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
        let restoreRoot = restoreStagingGenerationURL(id: id)
        let staging = generationRootURL.standardizedFileURL == restoreRoot.standardizedFileURL
        let epoch: GenerationEpochV1?
        let readerLease: GenerationLeaseHandleV1?
        let acceptedInstalledGeneration: Bool
        if staging {
            acceptedInstalledGeneration = false
        } else {
            let authority = try makeRestoreGenerationAuthority()
            acceptedInstalledGeneration = try authority.currentGenerationID() == id
                || authority.retiredGenerationIDs().contains(id)
        }
        diagnosticPhase?("generation-open.accepted-check.done")
        if acceptedInstalledGeneration {
            guard let manifest = try StoreMigrationJournalStoreV1(
                applicationSupportURL: applicationSupportURL
            ).loadManifestIfPresent(targetGenerationID: id),
                  manifest.manifest.generationID == id else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let acceptedEpoch = try GenerationEpochV1(
                generationID: id,
                generationManifestSHA256: manifest.digest
            )
            epoch = acceptedEpoch
            readerLease = try acquireAcceptedReaderLease(epoch: acceptedEpoch)
        } else {
            epoch = nil
            readerLease = nil
        }
        let retirementConstruction = try eraseReaderRetirementInventory?
            .beginConstruction(reader: readerLease)
        defer { retirementConstruction?.constructionInProgress = false }
        diagnosticPhase?("generation-open.lease.done")
        guard try itemType(at: generationRootURL) == .typeDirectory else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
        try protectGeneration(at: generationRootURL, staging: staging, requireModel: true)
        diagnosticPhase?("generation-open.pre-protection.done")
        let modelStoreURL = generationRootURL.appendingPathComponent(
            Self.modelStoreName,
            isDirectory: false
        )
        guard try itemType(at: modelStoreURL) == .typeRegular else {
            throw StoreGenerationFailure.dataGenerationMissing
        }
        let container: ModelContainer
        do {
            diagnosticPhase?("reviews.staging.container.begin")
            retirementConstruction?.constructorStarted = true
            container = try makeV53Container(at: modelStoreURL, migrate: false)
            retirementConstruction?.container = container
            retirementConstruction?.context = container.mainContext
            diagnosticPhase?("reviews.staging.marker.begin")
            _ = try requireV53Marker(in: container.mainContext, expectedMigrationID: nil)
            diagnosticPhase?("reviews.staging.marker.end")
        }
        catch {
#if DEBUG
            diagnosticPhase?("generation-open.container-or-marker.failed.type." + String(reflecting: type(of: error)))
#endif
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try protectGeneration(at: generationRootURL, staging: staging, requireModel: true)
        diagnosticPhase?("generation-open.post-protection.done")
        let resolvedIdentity = identity ?? pointerEnrichmentIdentity
        let session = StoreGenerationSession(
            generationID: id,
            generationRootURL: generationRootURL,
            workspaceIdentity: resolvedIdentity,
            modelContainer: container,
            storeSchemaRelease: PersistentSchemaReleaseRegistryV1.activeRelease,
            generationEpoch: epoch,
            readerLeaseHandle: readerLease,
            afterSaveReproof: { [factory = self.forSaveReproof()] in
                try factory.protectGeneration(
                    at: generationRootURL,
                    staging: staging,
                    requireModel: true
                )
            }
        )
        retirementConstruction?.session = session
        return session
    }

    private func removeOwnedDirectory(
        _ url: URL,
        expectedParent: URL
    ) throws {
        let value = url.standardizedFileURL
        guard value.deletingLastPathComponent() == expectedParent.standardizedFileURL,
              let id = UUID(uuidString: value.lastPathComponent),
              canonicalString(for: id) == value.lastPathComponent else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let parent = try openOwnedDirectory(at: expectedParent)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: expectedParent, descriptor: parent)
        let name = value.lastPathComponent
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        defer { _ = Darwin.close(descriptor) }
        let identity = try StoreRestoreGenerationAuthority.directoryIdentity(descriptor: descriptor)
        let revalidatePlacement = {
            try self.verifyOwnedDirectory(at: expectedParent, descriptor: parent)
            guard try StoreRestoreGenerationAuthority.requiredDirectoryIdentity(parent: parent, name: name) == identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try StoreRestoreGenerationAuthority.removeContents(of: descriptor, authorityCheck: revalidatePlacement)
        try revalidatePlacement()
        guard Darwin.unlinkat(parent, name, AT_REMOVEDIR) == 0, Darwin.fsync(parent) == 0,
              try !StoreRestoreGenerationAuthority.itemExists(parent: parent, name: name) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func decodeCanonicalPointer<Value: Decodable & Encodable>(
        at url: URL
    ) throws -> Value {
        let parentURL = url.deletingLastPathComponent()
        let parent = try openOwnedDirectory(at: parentURL)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: parentURL, descriptor: parent)
        return try decodeCanonicalPointer(parent: parent, name: url.lastPathComponent)
    }

    private func decodeCanonicalPointer<Value: Decodable & Encodable>(
        parent: Int32,
        name: String
    ) throws -> Value {
        do {
            let captured = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: name
            )
            let data = captured.data
            let value = try JSONDecoder().decode(Value.self, from: data)
            guard try canonicalData(for: value) == data else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            guard try StoreRestoreGenerationAuthority.regularFileIdentity(
                parent: parent,
                name: name
            ) == captured.identity else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return value
        } catch let failure as StoreGenerationFailure {
            throw failure
        } catch {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func canonicalData<Value: Encodable>(for value: Value) throws -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        return try encoder.encode(value)
    }

    private func canonicalUUID(from value: String) -> UUID? {
        guard let uuid = UUID(uuidString: value),
              canonicalString(for: uuid) == value else {
            return nil
        }
        return uuid
    }

    private func canonicalString(for uuid: UUID) -> String {
        uuid.uuidString.lowercased()
    }

    private func itemType(at url: URL) throws -> FileAttributeType? {
        var info = stat()
        guard Darwin.lstat(url.path, &info) == 0 else {
            if errno == ENOENT { return nil }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        switch info.st_mode & S_IFMT {
        case S_IFDIR:
            return .typeDirectory
        case S_IFREG:
            return .typeRegular
        case S_IFLNK:
            return .typeSymbolicLink
        default:
            return .typeUnknown
        }
    }
}

private final class StoreGenerationLeaseRegistryProvider: @unchecked Sendable {
    private let lock = NSLock()
    private var retainedRegistry: GenerationLeaseRegistryV1?

    func registry(
        applicationSupportURL: URL
    ) throws -> GenerationLeaseRegistryV1 {
        lock.lock()
        defer { lock.unlock() }
        if let retainedRegistry {
            return retainedRegistry
        }
        let registry = try GenerationLeaseRegistryV1(
            applicationSupportURL: applicationSupportURL
        )
        retainedRegistry = registry
        return registry
    }
}

