/// Validation must still encode every local envelope: its values may reject during
/// Encodable conformance. Its already validated predecessor does not need to be
/// base64-encoded again. Canonical migration consumers keep the original bytes.
private struct StoreSemanticExportPurposeV1 {
    let retainsCanonicalBytes: Bool
    var consumeLayer: ((Data) throws -> Void)? = nil
#if DEBUG
    var didEncode: ((Data) -> Void)? = nil
#endif

    static let canonicalBytes = Self(retainsCanonicalBytes: true)
    static let validationOnly = Self(retainsCanonicalBytes: false)

    func encode<Value: Encodable>(_ value: Value) throws -> Data {
        let bytes = try StoreMigrationCanonicalJSONV1.encode(value)
        try consumeLayer?(bytes)
#if DEBUG
        didEncode?(bytes)
#endif
        return retainsCanonicalBytes ? bytes : Data()
    }
}

