            for (name, kind) in [("model.sqlite-wal", OwnedFileKindV1.databaseWAL), ("model.sqlite-shm", OwnedFileKindV1.databaseSHM)] {
                var value = stat()
                if Darwin.fstatat(generation, name, &value, AT_SYMLINK_NOFOLLOW) != 0 {
